real h=sqrt(3),d=2/sqrt(3),r=2-sqrt(3);draw((-1,0)--(0,h)--(1,0)--cycle);draw((-1.3,0)--(1.7,0));draw(circle((d,r),r));draw((0,0)--(0,h),dashed);dot((d,r));label("$r$",(d+r,r),E);label("$\sqrt{3}$",(0,h/2),W);label("$1$",(.5,0),S);
\end{asy}

Put $B=(0,0)$, $C=(14,0)$, $A=(u,12)$, $D=(u+14,12)$. Since $AB=13$, $u^2+144=169$, giving $u=\pm5$. Point $E$ has $x=14$ on segment $BD$, so its parameter is $t=\dfrac{14}{14+u}\in[0,1]$. The choice $u=-5$ would give $t>1$ and is excluded. Thus $u=5$, $t=\dfrac{14}{19}$ and $CE=12t=\boxed{\dfrac{168}{19}}$.
