pair O=(0,0),X=(3,0),Y=(1.2,.8),Z=(0,3);draw(O--X--(X+Y)--Y--cycle,dashed);draw(Z--(Z+X)--(Z+X+Y)--(Z+Y)--cycle);draw(O--Z);draw(X--(X+Z));draw(Y--(Y+Z),dashed);draw((X+Y)--(X+Y+Z));draw(O--Z--(Z+Y)--(Z+X+Y)--O,blue);draw(O--(Z+Y),blue+dashed);draw(Z--(Z+X+Y),blue+dashed);label("$(0,0,0)$",O,SW);label("$(0,0,1)$",Z,NW);label("$(0,1,1)$",Z+Y,N);label("$(1,1,1)$",Z+X+Y,NE);label("$x$",X,S);label("$y$",Y,W);
\end{asy}

Let $A=(a,0)$, $B=(0,b)$ and $P=(20,25)$. The two possible equilateral third vertices on $AB$ are $\left(\dfrac{a\pm\sqrt3b}{2},\dfrac{b\pm\sqrt3a}{2}\right)$, with matching signs. Equating to $P$ gives $a\pm\sqrt3b=40$ and $b\pm\sqrt3a=50$. Solving gives $(a,b)=(-20\pm25\sqrt3,-25\pm20\sqrt3)$; positivity selects the plus signs. The squared side length is $a^2+b^2=4100-2000\sqrt3$. Therefore the area is $\dfrac{\sqrt3}{4}(4100-2000\sqrt3)=\boxed{25(41\sqrt3-60)}$.
\begin{asy}
usepackage("amsmath");
