pair A=(0,0),B=(51,0),C=(68,68sqrt(3)),Cp=(68,-68sqrt(3)),Bp=(-25.5,-25.5sqrt(3));draw(A--B--C--cycle);draw(A--Cp,dashed);draw(Bp--Cp--C--cycle,blue);draw(B--Bp,dashed);label("$A$",A,W);label("$B$",B,N);label("$C$",C,N);label("$C^{\prime}$",Cp,S);label("$B^{\prime}$",Bp,W);
