pair A=(0,0),B=(3,7),C=(4,5);draw(A--B--(B+C)--C--cycle,blue);draw(B--A--(C-B)--C--cycle,red+dashed);draw(C--A--(B-C)--B--cycle,green+dotted);dot(A);dot(B);dot(C);
