Unfold any sequence of crossed faces into the plane. A shortest path does not revisit a face, since the straight chord inside that convex face shortens such a revisit. It also cannot pass through a vertex: the total face angle there is 240 degrees, so one side of the path has angle less than 180 degrees and can be shortened. Thus it suffices to check simple paths in the dual cube, of which there are 18. The following exact certificate unfolds all of them and retains only straight segments crossing each shared edge in order and in its interior. Coordinates $(u,v)$ in the code represent $(u,v\sqrt3)$, so squared lengths are $u^2+3v^2$.\begin{verbatim}
from fractions import Fraction as F
from itertools import product
faces=list(product([0,1],[2,3],[4,5]))
start,goal=faces[0],faces[-1]
def sub(a,b):return (a[0]-b[0],a[1]-b[1])
def dot(a,b):return a[0]*b[0]+3*a[1]*b[1]
def cross(a,b):return a[0]*b[1]-a[1]*b[0]
def reflect(p,a,b):
 v=sub(b,a);t=dot(v,sub(p,a))/dot(v,v)
 return (2*(a[0]+t*v[0])-p[0],2*(a[1]+t*v[1])-p[1])
P=(F(1),F(1,3)); lengths=[]; path_count=0
def search(face,coords,used,edges):
 global path_count
 if face==goal:
  path_count+=1
  Q=tuple(sum(coords[v][j] for v in face)/3 for j in [0,1])
  vec=sub(Q,P);last=0
  for a,b in edges:
   e=sub(b,a);w=sub(a,P);den=cross(vec,e)
   if not den:return
   t=cross(w,e)/den;u=cross(w,vec)/den
   if not(last<t<1 and 0<u<1):return
   last=t
  lengths.append(dot(vec,vec));return
 for nxt in faces:
  shared=set(face)&set(nxt)
  if len(shared)!=2 or nxt in used:continue
  a,b=[coords[v] for v in shared]
  old=next(v for v in face if v not in shared)
  new=next(v for v in nxt if v not in shared)
  cc={v:coords[v] for v in shared}
  cc[new]=reflect(coords[old],a,b)
  search(nxt,cc,used|{nxt},edges+[(a,b)])
search(start,{0:(F(0),F(0)),2:(F(2),F(0)),4:(F(1),F(1))},{start},[])
assert path_count==18 and min(lengths)==F(28,3)
\end{verbatim}
