from itertools import product
valid=[]
for p in product('DM',repeat=11):
 x=1
 for op in p:x=2*x if op=='D' else x-1
 if x==120:valid.append(''.join(p))
assert valid==['DDDDDDMMMMD','DDDDDMDMDMM','DDMMDDDMDDD','DMDDDDDMMDD']
\end{verbatim}

