draw((0,0)--(1,0)--(1,1)--(0,1)--cycle);filldraw((1,0)--(1,1)--(0,1)--cycle,lightgray);label("$x$",(1,0),SE);label("$y$",(0,1),NW);label("$x+y>1$",(.65,.65));
\end{asy}

Write position vectors with $A=0$, $B=u$, $C=v$. Then $E=eu$, $F=fv$, where $e=\dfrac{AE}{12}$, $f=\dfrac{AF}{16}$, so $\dfrac{e}{f}=\dfrac{8}{3}$. If $G=(1-t)E+tF$, lying on the median means the coefficients of $u,v$ agree: $(1-t)e=tf$. Hence $EG:GF=t:(1-t)=e:f=\boxed{8:3}$.
\begin{asy}
usepackage("amsmath");
size(7cm);
pair A=(0,0),Bp=(12,0),C=(0,16),M=(Bp+C)/2,Ep=(8,0),F=(0,4),G=(24/11,32/11);draw(A--Bp--C--cycle);draw(A--M,dashed);draw(Ep--F,blue);label("$A$",A,SW);label("$B$",Bp,SE);label("$C$",C,N);label("$M$",M,NE);label("$E$",Ep,S);label("$F$",F,W);label("$G$",G,NE);
\end{asy}

Place $B=(0,0)$, $A=(5,0)$, and $C=(\dfrac{3}{\sqrt2},\dfrac{3}{\sqrt2})$. Write $M=(m,0)$. The three isosceles cases $BM=BC$, $CM=BC$, and $BM=CM$ give respectively $m=\pm3$, $m=3\sqrt2$ (discarding the degenerate $m=0$), and $m=\dfrac{3}{\sqrt2}$. In affine coordinates based at $B$ with directions $A,C$, the line $CM$ meets $AD$ at $N=A+(1-\dfrac{5}{m})C$. Therefore $[MAN]=\dfrac{3(m-5)^2}{2\sqrt2|m|}$. At the four admissible values this is $16\sqrt2$, $\sqrt2$, $\dfrac{43-30\sqrt2}{4}$, and $\dfrac{59}{4}-\dfrac{15\sqrt2}{2}$. The greatest is $\boxed{16\sqrt2}$, attained at $m=-3$.
\begin{asy}
usepackage("amsmath");
size(7cm);
pair Bp=(0,0),A=(5,0),C=(3/sqrt(2),3/sqrt(2)),D=A+C,M=(-3,0),Np=A+(8/3)*C;draw(A--Bp--C--D--cycle,gray);draw(M--A--Np--cycle,blue);draw(M--C--Np);label("$A$",A,S);label("$B$",Bp,S);label("$C$",C,NW);label("$D$",D,E);label("$M$",M,W);label("$N$",Np,N);
\end{asy}

The homothety centered at $B$ with ratio $-2$ sends $A$ to $D$ and $C$ to $E$, so it sends the first circumcircle of radius $R$ to the second of radius $2R$. Since both circles pass through $B$, their centers are on opposite sides of $B$ and are $3R$ apart. The external common-tangent segment therefore has length $\sqrt{(3R)^2-(2R-R)^2}=2\sqrt2R$. Heron's formula gives the original triangle area $\dfrac{15\sqrt7}{4}$, so $R=\dfrac{4\cdot5\cdot6}{15\sqrt7}=\dfrac{8}{\sqrt7}$. Hence $\boxed{MN=\dfrac{16\sqrt{14}}{7}}$.
\begin{asy}
usepackage("amsmath");
size(7cm);
pair Bp=(0,0),O1=(-1,0),O2=(2,0),u=(-1/3,sqrt(8)/3),M=O1+u,Np=O2+2*u;draw(circle(O1,1));draw(circle(O2,2));draw(M--Np,blue);draw(O1--M,dashed);draw(O2--Np,dashed);draw(O1--O2,gray);label("$B$",Bp,S);label("$O_1$",O1,S);label("$O_2$",O2,S);label("$M$",M,N);label("$N$",Np,N);
\end{asy}

Each triangle has angle sum $180^\circ$, so the combined total is $4\cdot180^\circ=\boxed{720^\circ}$.
