usepackage("amsmath");
size(7cm);
draw(circle((0,1),1));draw((-1.5,0)--(1.5,0));dot((0,0));label("bottom",(0,0),S);draw(arc((0,1),0.7,-80,0),Arrow);label("unit circle",(0,2),N);
\end{asy}

