real a=15;real r=39/(4*cos(a*pi/180)^2-1);pair A=(0,0),B=(39,0),D=(20,0),PtE=2*r*cos(a*pi/180)*dir(a);draw(A--B--PtE--cycle);draw(D--PtE,blue);label("$A$",A,SW);label("$B$",B,SE);label("$D$",D,S);label("$E$",PtE,N);
