Tile the first empty cell with a unit square, a horizontal domino, or a vertical domino whenever available. Recursing counts each tiling once and gives $\boxed{22}$:
\begin{verbatim}
from functools import lru_cache
@lru_cache(None)
def f(mask):
 if mask==63:return 1
 k=next(i for i in range(6) if not(mask>>i&1));r,c=divmod(k,3)
 ans=f(mask|(1<<k))
 for j in ([k+1] if c<2 else [])+([k+3] if r==0 else []):
  if not(mask>>j&1):ans+=f(mask|(1<<k)|(1<<j))
 return ans
assert f(0)==22
\end{verbatim}
