Testing the 24 assignments, discarding division by zero, gives uniquely $h=\div,d=-,c=\times,s=+$. The required expression becomes $\left(\dfrac{64+8}{6}+5\right)\cdot7-1=118$. The following exact rational check verifies uniqueness and the answer $\boxed{118}$.
\begin{verbatim}
from itertools import permutations
from fractions import Fraction as F
ops={'+':lambda a,b:a+b,'-':lambda a,b:a-b,
     '*':lambda a,b:a*b,'/':lambda a,b:a/b}
valid=[]
for h,d,c,s in permutations(ops):
    try:
        v=ops[h](ops[c](ops[d](ops[s](ops[d](F(72),F(36)),F(0)),F(32)),F(3)),F(2))
        if v==6:valid.append((h,d,c,s))
    except ZeroDivisionError:pass
assert valid==[('/','-','*','+')]
\end{verbatim}

