pair A=(-1,12),B=(1,12),C=(3,0),D=(-3,0),Ee=(0,9);draw(A--B--C--D--cycle);draw(A--C);draw(B--D);label("$A$",A,NW);label("$B$",B,NE);label("$C$",C,SE);label("$D$",D,SW);label("$E$",Ee,E);
\end{asy}

Let its positive integer dimensions be $a,b,h$. Then $a+b=27$ and $abh=144$, so $ab$ divides $144$. Assume $a\le b$. Testing $1\le a\le13$ in $a(27-a)\mid144$ gives only $a=3,b=24$, for which $ab=72$. (The products are $26,50,72,92,110,126,140,152,162,170,176,180,182$.) Hence $h=\dfrac{144}{72}=\boxed2$.
\begin{asy}
