pair A=(2,0),B=(1,sqrt(15)),C=(-3,-sqrt(15)); draw(A--B--C--cycle); draw(A--(B+C)/2^^B--(A+C)/2^^C--(A+B)/2,dashed); dot((0,0)); label("$G$",(0,0),S); label("$A$",A,E);label("$B$",B,N);label("$C$",C,S); pair U=(11,0),V=(8,sqrt(15)),PtW=(8,-sqrt(15));draw(U--V--PtW--cycle);draw(U--(V+PtW)/2^^V--(U+PtW)/2^^PtW--(U+V)/2,dashed);label("equal medians",(9,-5));
\end{asy}

