draw(circle((0,0),25));draw((-28,0)--(28,0)^^(0,-28)--(0,28),gray);for(int x=-25;x<=25;++x)for(int y=-25;y<=25;++y)if(x*x+y*y==625)dot((x,y));label("$(7,24)$",(7,24),N);label("$(15,20)$",(15,20),E);label("$(25,0)$",(25,0),SE);label("$(0,-25)$",(0,-25),S);
\end{asy}

Place the chord intersection at the origin and the chords on the coordinate axes. If the centre is $(u,v)$ and radius is $R$, then $u^2+v^2=36$, and the half-chord formulas give $R^2-v^2=\dfrac{121}{4}$, $R^2-u^2=\dfrac{225}{4}$. Adding yields $2R^2-36=\dfrac{346}{4}$. Hence the diameter squared is $4R^2=\boxed{245}$.
\begin{asy}
usepackage("amsmath");
size(7cm);
pair O=(sqrt(5),sqrt(31)),P=(0,0);real R=sqrt(245)/2;draw(circle(O,R));draw((O.x-5.5,0)--(O.x+5.5,0));draw((0,O.y-7.5)--(0,O.y+7.5));draw(O--P,dashed);label("$O$",O,E);label("$P$",P,SW);label("$11$",(O.x,0),S);label("$15$",(0,O.y),W);label("$6$",O/2,SE);
\end{asy}

Choose coordinates $ A=(0,0),B=(b,0),D=(u,v)$, where $ b>0 $ and $ v\ne0 $. Then $ C=(b+u,v)$, $ H=(\dfrac{b+u}{2},0)$ and $ G=(\dfrac{2b+u}{3},\dfrac{v}{3})$. Thus \[HD^2=\dfrac{(u-b)^2}{4}+v^2,\qquad HG^2=\dfrac{(b-u)^2}{36}+\dfrac{v^2}{9}.\]The first is nine times the second. Taking nonnegative square roots proves $ HD=3HG $.
\begin{asy}
usepackage("amsmath");
size(7cm);
pair A=(0,0),B=(5,0),D=(1,3),C=B+D,O=C/2,H=(O.x,0),G=(A+B+C)/3;draw(A--B--C--D--cycle);draw(O--H^^H--D^^H--G,dashed);dot(O);dot(G);label("$A$",A,SW);label("$B$",B,SE);label("$C$",C,NE);label("$D$",D,NW);label("$O$",O,N);label("$H$",H,S);label("$G$",G,E);
\end{asy}

Use a unit circumcircle with $A=(0,1)$ and symmetry about the vertical axis. Then $F=(-\dfrac{\sin72^\circ}{2},\dfrac{1+\cos72^\circ}{2})$, $H$ is its reflection, and $G=(0,-\cos36^\circ)$. Half the requested angle has tangent $\dfrac{\sin72^\circ}{1+\cos72^\circ+2\cos36^\circ}=\dfrac{\sin36^\circ}{1+\cos36^\circ}=\tan18^\circ$. This acute half-angle is 18 degrees, so $\boxed{\angle FGH=36^\circ}$.
\begin{asy}
