from itertools import permutations
good=[]
for F,S,T,R,X,Y in permutations([2,3,4,6,7,8]):
 if S==F+1 and 2*T+R+1==X+20:
  good.append((F,S,T,R,X,Y))
assert good==[(2,3,8,7,4,6)]
\end{verbatim}

