pair C=(0,0),L=(0.25,0),F=(1.21,0),P=(0.25,sqrt(6)/5);draw(C--P--F--cycle);draw(P--L,dashed);label("$C$",C,SW);label("$L$",L,S);label("$F$",F,SE);label("$P$",P,N);
