defaultpen(fontsize(10pt));
void box(pair o,real w,real d,real h,real f){pair x=(w,0),y=0.45*(d,d)*0.7,z=(0,h);
fill(o--o+x--o+x+(0,f)--o+(0,f)--cycle,lightgray);draw(o--o+x--o+x+z--o+z--cycle);draw(o+z--o+z+y--o+x+z+y--o+x+z);draw(o+x--o+x+y--o+x+y+z);}
