size(5cm);
defaultpen(fontsize(10pt));
pair C=(0,0),A=(0,15),B=(20,0),P=(0,8),Q=(13,0);pair X=extension(A,Q,B,P);
fill(A--P--X--cycle,gray(0.85));fill(B--Q--X--cycle,gray(0.6));
draw(A--B--C--cycle);draw(A--Q);draw(B--P);
draw(C+(0.8,0)--C+(0.8,0.8)--C+(0,0.8));
label("$A$",A,N);label("$B$",B,SE);label("$C$",C,SW);label("$P$",P,W);label("$Q$",Q,S);label("$X$",X,N);
label("$7$",(0,11.5),W);label("$7$",(16.5,0),S);
