draw(circle(O,5));draw(A--B);draw(A--M--B);draw(M--P,dashed);draw(A--P);draw(O--M,dotted);
dot(O);label("$A$",A,W);label("$B$",B,E);label("$M$",M,NE);label("$O$",O,S);label("$P$",P,NW);
\end{asy}

