for(int i : new int[]{1,3}){pair m=(V[i]+V[(i+1)%5])/2;pair apex=m+sqrt(3)*unit(m);draw(V[i]--apex--V[(i+1)%5]);}
label("$\cdots$",(2.6,-0.6));label("$\cdots$",(-2.6,-0.6));
