defaultpen(fontsize(10pt));
pair A=(-4,0),B=(4,0),M=(0,0);pair C=(-0.5,sqrt(15.75));
draw(A--B--C--cycle);draw(M--C,dashed);draw(arc(M,4,0,180),dotted);label("$A$",A,W);label("$B$",B,E);label("$C$",C,N);label("$M$",M,S);label("$6$",(B+C)/2,NE);
