defaultpen(fontsize(10pt));
import graph;real f(real x){return x^2-x-2;}draw(graph(f,-1.8,3.6));draw((-1.8,-0.8)--(3.6,4.6));dot((-1,0));dot((3,4));label("$(-1,0)$",(-1,0),W);label("$(3,4)$",(3,4),E);draw((-2,0)--(4,0),Arrow);draw((0,-2.5)--(0,6),Arrow);
