defaultpen(fontsize(10pt));
pair[] V;for(int k=0;k<5;++k) V.push(dir(90+72*k));
draw(V[0]--V[1]--V[2]--V[3]--V[4]--cycle,linewidth(1));
draw(V[0]--V[2]--V[4]--V[1]--V[3]--cycle,dashed);
for(int k=0;k<5;++k) dot(V[k]);
label("$s$",(V[0]+V[1])/2,NW);label("$d$",(V[0]+V[2])/2,E);
