pair[] V;for(int k=0;k<8;++k) V.push(dir(90-45*k));
draw(unitcircle,gray);
int[] cyc={0,2,4,6,7,5,3,1};
for(int k=0;k<8;++k){draw(V[cyc[k]]--V[cyc[(k+1)%8]]);}
for(int k=0;k<8;++k){dot(V[k]);label("$"+string(k)+"$",1.15*V[k]);}
\end{asy}

Put $A=(0,0)$, $B=(1,0)$, $C=(0,1)$, with $M=\left(\dfrac12,0\right)$ and $N=\left(0,\dfrac12\right)$ the midpoints of $AB$ and $AC$. The medians $BN$ and $CM$ meet at the centroid $G=\left(\dfrac13,\dfrac13\right)$.
