\emph{Numbers with a pair.}
\begin{itemize}
\item If $n$ has a digit $0$, then appending another $0$ keeps the digit sum and the product $0$.
\item If $n$ has no $0$ but two different digits, rearranging its digits gives a different number.
\end{itemize}
So only repdigits $\overline{dd\cdots d}$ ($k$ copies of $d\ge1$) can lack a pair, with sum $kd$ and product $d^k$. Any partner must also have no $0$ digit.
\begin{itemize}
\item $d=4,6,8,9$: one digit can be replaced, keeping sum and product: $4\to22$, $6\to123$, $8\to1124$, $9\to11133$.
\item $d=2$, $k\ge2$: replace $22$ by $4$.
\end{itemize}

\emph{Numbers without a pair.} Suppose $m$ has digit sum $kd$ and digit product $d^k$.
\begin{itemize}
\item $d=1$: all digits of $m$ are $1$, and there are $k$ of them, so $m=n$.
\item $d=5$ or $7$: the digits of $m$ are $d$'s and $1$'s. The product forces $k$ copies of $d$, and the sum then forces no $1$'s, so $m=n$.
\item $d=3$: the digits of $m$ are $1$'s, $a$ threes and $b$ nines with $a+2b=k$. The digit sum is at least $3a+9b=3k+3b$, which equals $3k$ only if $b=0$ and there are no $1$'s, so $m=n$.
\item $n=2$: a digit product of $2$ means one $2$ and some $1$'s, and the sum $2$ allows no $1$'s.
\end{itemize}

So the numbers belonging to no good pair are
\[\boxed{2,\ \text{and all of }1\cdots1,\ 3\cdots3,\ 5\cdots5,\ 7\cdots7\text{ (any number of digits)}}.\]

