defaultpen(fontsize(10pt));
real dd=2.02;pair u=(dd,0),v=dd*dir(60);
for(int i=-1;i<=3;++i) for(int j=0;j<=2;++j){pair c=i*u+j*v-(j#2)*u;if(c.x>-1.5 && c.x<7) draw(circle(c,1),gray);}
pair[] P={(0.3,0.4),(-0.5,-0.3),(2.3,0.6),(1.6,-0.5),(4.4,0.2),(1.2,1.9),(3.3,2.0),(2.6,1.3),(0.3,3.6),(2.3,3.3)};
for(int i=0;i<P.length;++i) dot(P[i]);
draw((5.6,-1.2)--(6.5,-0.6),Arrow(4));label("$t$",(6.05,-0.9),SE);
\end{asy}

(The sketch shows part of the slightly loosened hexagonal packing; it is translated by a suitable vector $t$ until every person is covered.)

\textbf{Yes.} Let $O$ be the centre.

\emph{First step.} From $O$ any step leaves you at distance $1$ from $O$.

\emph{Later steps.} If you are at $P$ with $OP=r>0$, face along the line through $P$ perpendicular to $OP$. Whether the adversary sends you forward or backward, you land at a point $P'$ or $P''$ with $PP'=1$ and $\angle OPP'=90^\circ$, so by the Pythagorean theorem your new distance from $O$ is $\sqrt{r^2+1}$.

