pair O=(0,0);
for(int k=2;k<=11;++k) draw(O--Q(k-1)--Q(k)--cycle,gray(0.55));
draw(O--Q(0)--Q(1)--cycle,linewidth(0.9));
draw(O--Q(11)--Q(12)--cycle,linewidth(0.9));
