size(7cm);
defaultpen(fontsize(10pt));
pair B=(0,0),A=(1,0),C=(3,0);
draw((-0.3,0)--(3.3,0),gray);dot(B);dot(A);dot(C);
label("$B$",B,S);label("$A$",A,S);label("$C$",C,S);
label("$\angle ABC=\angle ACB=0^\circ$",(1.5,0.35),fontsize(8pt));
pair P=(5,0),Q=(7.4,0),R=(6.2,1.6);
draw(P--Q--R--cycle,linewidth(0.8));
draw(arc(P,0.45,0,degrees(R-P)));draw(arc(Q,0.45,degrees(R-Q),180));
label("$B$",P,SW);label("$C$",Q,SE);label("$A$",R,N);
\end{asy}

question:
For a function $f$, define $a(x)=\dfrac12f(x)$ and $b(x)=f\left(\dfrac x2\right)$.
\begin{enumerate}
\item[(a)] Describe how the graphs of $y=a(x)$ and $y=b(x)$ are obtained from the graph of $y=f(x)$.
\item[(b)] For $f(x)=x^2$, compute $a(4)$ and $b(4)$.
\item[(c)] Find all linear functions $f(x)=mx+c$ for which $a(x)=b(x)$ for every real $x$.
\end{enumerate}

solution:
Let the sides be $a\le b\le c$ with $a+b+c=20$. The triangle inequality reduces to $a+b>c$, i.e. $20-c>c$, so $c\le9$; and $3c\ge a+b+c=20$ gives $c\ge7$.
\begin{itemize}
\item $c=9$: $a+b=11$ with $a\le b\le9$: $(2,9),(3,8),(4,7),(5,6)$, i.e. $4$ triangles.
\item $c=8$: $a+b=12$ with $a\le b\le8$: $(4,8),(5,7),(6,6)$, i.e. $3$ triangles.
\item $c=7$: $a+b=13$ with $a\le b\le7$: $(6,7)$, i.e. $1$ triangle.
\end{itemize}
In total there are $\boxed{8}$ triangles, drawn below.

\begin{asy}
usepackage("amsmath");
size(9cm);
defaultpen(fontsize(10pt));
int[][] T={{2,9,9},{3,8,9},{4,7,9},{5,6,9},{4,8,8},{5,7,8},{6,6,8},{6,7,7}};
for(int k=0;k<8;++k){
 real a=T[k][0],bb=T[k][1],c=T[k][2];
 pair o=((k%4)*11,-(k#4)*9);
 real x=(c^2+bb^2-a^2)/(2c);pair P=o,Q=o+(c,0),R=o+(x,sqrt(bb^2-x^2));
 draw(P--Q--R--cycle,linewidth(0.7));
 label("$"+string(T[k][2])+"$",(P+Q)/2,S,fontsize(7pt));
 label("$"+string(T[k][1])+"$",(P+R)/2,unit((P.y-R.y,R.x-P.x)),fontsize(7pt));
 label("$"+string(T[k][0])+"$",(Q+R)/2,unit((R.y-Q.y,Q.x-R.x)),fontsize(7pt));}
\end{asy}

Translate every line so that it passes through a fixed point $O$. A translation does not change the direction of a line, so the angle between any two lines is unchanged, and the eight translated lines are still distinct (no two of the original lines are parallel).

Going around $O$, the eight lines through $O$ cut the half-turn from one ray of the first line to the opposite ray into eight consecutive angles between neighbouring lines, all positive, with total $180^\circ$. The smallest of them is at most $\dfrac{180^\circ}{8}=22.5^\circ<23^\circ$, and it is the angle between two of the lines. $\blacksquare$

