label("$-2$",(-2,0),SW,fontsize(8pt));label("$2$",(2,0),SE,fontsize(8pt));label("$1$",(1,0),S,fontsize(8pt));
label("$x=-2$",(-2,3.2),N,fontsize(8pt));label("$x=2$",(2,3.2),N,fontsize(8pt));
