label("$D$",P(0,0,0),SW);label("$A$",P(0,0,1),NW);label("$H$",P(0,1,0),W);label("$E$",P(0,1,1),N);
label("$C$",P(1,0,0),S);label("$B$",P(1,0,1),NW);label("$G$",P(1,1,0),E);label("$F$",P(1,1,1),NE);
