path p=(0,3)--(xs[0],3)--(xs[1],2)--(xs[2],1)--(xs[3],0)--(0,0)--cycle;
fill(p,paleblue);
draw((0,0)--(3,0)--(3,3)--(0,3)--cycle,gray);
