pair cc(pair P,pair Q,pair R){pair m1=(P+Q)/2, m2=(Q+R)/2; return extension(m1,m1+rotate(90)*(Q-P),m2,m2+rotate(90)*(R-Q));}
pair O=cc(A,B,C); real R=abs(A-O);
draw(circle(O,R),gray+dashed);
