draw(shift(m1)*rotate(degrees(D-A))*((0,-0.02)--(0,0.02)),red+linewidth(0.9));
draw(shift(m2)*rotate(degrees(Ep-C))*((0,-0.02)--(0,0.02)),red+linewidth(0.9));
