for(pair p:pts) dot(p);
label("$(2,3)$",(2,3),E,fontsize(8pt)); label("$(-2,3)$",(-2,3),W,fontsize(8pt));
label("$(1,-3)$",(1,-3),SE,fontsize(8pt)); label("$(-1,-3)$",(-1,-3),SW,fontsize(8pt));
label("$y=2x^2-5$",(2.3,f(2.3)),E,blue+fontsize(8pt));
\end{asy}

