label("$15$",(X+Np)/2,W,red+fontsize(8pt)); label("$20$",(Y+Np)/2,SE,red+fontsize(8pt)); label("$25$",(X+Y)/2+(5,0),N,blue+fontsize(8pt));
label("$12$",(Np.x,7),W,fontsize(8pt)); label("$30$",(B+C)/2+(6,0),S,fontsize(8pt));
\end{asy}

The sketches show the whole triangle and an enlarged view of its lower part. (For instance $B=(0,0)$, $C=(30,0)$, $A=(12,72)$, $X=(2,12)$, $Y=(27,12)$, $N=(11,0)$ satisfy all the conditions.)

\textbf{The triangle $ABC$.} $3x-2=5x+6$ gives $x=-4$, so $(-4,-14)$; $3x-2=2x$ gives $(2,4)$; $5x+6=2x$ gives $(-2,-4)$. By the shoelace formula,
\[[ABC]=\dfrac12\left|(-4)(4-(-4))+2\bigl((-4)-(-14)\bigr)+(-2)\bigl((-14)-4\bigr)\right|=\dfrac12\left|-32+20+36\right|=12.\]

\begin{asy}
usepackage("amsmath");
size(5cm);
defaultpen(fontsize(10pt));
import graph;
pair A=(-4,-14), B=(2,4), C=(-2,-4);
real u=0.28;
pair T(pair p){return (u*p.x,u*p.y);}
draw(T((-7,0))--T((7,0)),Arrow(5)); draw(T((0,-16))--T((0,9)),Arrow(5));
label("$x$",T((7,0)),E); label("$y$",T((0,9)),N);
fill(T(A)--T(B)--T(C)--cycle,rgb(0.85,0.9,1)); draw(T(A)--T(B)--T(C)--cycle,blue+linewidth(0.9));
draw(T((5,-16))--T((5,9)),red+dashed); label("$x=5$",T((5,9)),N,red+fontsize(8pt));
dot(T(A)); dot(T(B)); dot(T(C));
label("$(-4,-14)$",T(A),W,fontsize(7pt)); label("$(2,4)$",T(B),E,fontsize(7pt)); label("$(-2,-4)$",T(C),W,fontsize(7pt));
\end{asy}

\textbf{The tilted copy.} Use space coordinates $(x,y,z)$ with the coordinate plane as $z=0$. A plane through the line $x=5$, $z=0$ at angle $30^\circ$ to $z=0$ is $z=t(x-5)$ with $t=\pm\tan30^\circ$. The vertical line through $(p,q,0)$ meets it at $(p,q,t(p-5))$. So if $\vec u=(u_1,u_2)$ and $\vec v=(v_1,v_2)$ are two edge vectors of $ABC$, the corresponding edges of $A'B'C'$ are $(u_1,u_2,tu_1)$ and $(v_1,v_2,tv_1)$, whose cross product is
\[\bigl(t(u_2v_1-u_1v_2),\ 0,\ u_1v_2-u_2v_1\bigr),\qquad\text{of length }|u_1v_2-u_2v_1|\sqrt{1+t^2}.\]
Hence $[A'B'C']=[ABC]\sqrt{1+\tan^230^\circ}=\dfrac{[ABC]}{\cos30^\circ}$, i.e. the area is divided by the cosine of the angle between the planes. Therefore
\[[A'B'C']=\dfrac{12}{\dfrac{\sqrt3}{2}}=\dfrac{24}{\sqrt3}=8\sqrt3=\dfrac{8\sqrt3}{1}.\]
So $x=8$, $y=3$, $z=1$ and $xyz=\boxed{24}$.

\textbf{Two isosceles triangles.} Since $AI$ bisects $\angle A$ and $MI\parallel AC$,
\[\angle MIA=\angle IAC=\angle IAM,\]
so triangle $AMI$ is isosceles with $MI=AM=4$. In the same way $\angle NIC=\angle ICA=\angle ICN$, so $NI=NC$. Hence $NC=MN-MI=7-4=3$.

\textbf{The angles.} The line $\ell$ is at distance $2$ (the inradius) from $AC$, so $M$ and $N$ are at height $2$ above $AC$:
\[\sin A=\dfrac{2}{AM}=\dfrac12,\qquad\sin C=\dfrac{2}{NC}=\dfrac23.\]
$C$ is acute, so $\cos C=\dfrac{\sqrt5}{3}$, and $C=\arcsin\dfrac23>30^\circ$ (as $\dfrac23>\dfrac12$). If $A$ were $150^\circ$, then $A+C>180^\circ$; so $A=30^\circ$ and $\cos A=\dfrac{\sqrt3}{2}$.

\textbf{The base $AC$.} Drop perpendiculars from $M$ and $N$ to $AC$. Their feet are at distances $AM\cos A=2\sqrt3$ from $A$ and $NC\cos C=\sqrt5$ from $C$, and are $MN=7$ apart, since $MN\parallel AC$. As both angles are acute,
\[AC=2\sqrt3+7+\sqrt5.\]

\textbf{The area.} $AMNC$ is a trapezoid with parallel sides $MN=7$ and $AC$ and height $2$:
\[[AMNC]=\dfrac{7+AC}{2}\cdot2=14+2\sqrt3+\sqrt5.\]
So $a=14$, $b=2$, $c=1$ and $a+b+c=\boxed{17}$.

\begin{asy}
usepackage("amsmath");
size(6.5cm);
defaultpen(fontsize(10pt));
real r=2;
pair A=(0,0);
real Cang=aSin(2/3);
real b=7+2*sqrt(3)+sqrt(5);
pair C=(b,0);
pair B=extension(A,A+dir(30),C,C+dir(180-Cang));
pair I=(2*sqrt(3)+4,2);
pair M=extension(A,B,I,I+(1,0)), Nn=extension(C,B,I,I+(1,0));
fill(A--M--Nn--C--cycle,rgb(0.88,0.92,1));
draw(A--B--C--cycle,linewidth(0.9));
draw(circle(I,r),blue);
draw(M--Nn,red+linewidth(0.9));
draw(I--(I.x,0),dashed); draw(A--I,dotted); draw(C--I,dotted);
