 real ux=((a.x^2+a.y^2)*(b.y-c.y)+(b.x^2+b.y^2)*(c.y-a.y)+(c.x^2+c.y^2)*(a.y-b.y))/d;
 real uy=((a.x^2+a.y^2)*(c.x-b.x)+(b.x^2+b.y^2)*(a.x-c.x)+(c.x^2+c.y^2)*(b.x-a.x))/d; return (ux,uy);}
