draw(arc(A,0.45,degrees(B-A),degrees(C-A)),orange); label("$60^\circ$",A+0.85*dir(-56),orange+fontsize(8pt));
dot(H,blue); dot(I,red);
label("$A$",A,N);label("$B$",B,SW);label("$C$",C,SE);label("$H$",H,dir(-62),blue);label("$I$",I,dir(85),red);
