real h=sqrt(3)/2;
pair pt(real a,real bb){return (a+bb/2,bb*h);}
for(int i=1;i<16;++i){
  draw(pt(0,i)--pt(16-i,i),linewidth(0.3));
  draw(pt(i,0)--pt(i,16-i),linewidth(0.3));
