usepackage("amsmath");
size(6.5cm);
defaultpen(fontsize(10pt));
pair O=(6,0), F=(0,0), C=(12,0);
pair A=O+6*dir(120), B=O+6*dir(60), D=O+6*dir(-60), pE=O+6*dir(-120);
pair G=12*dir(60), H=12*dir(240);
draw(circle(F,12),gray);
draw(A--B--C--D--pE--F--cycle,linewidth(0.8));
draw(H--G,blue);
draw(F--C,dashed);
draw(G--C--H,red+linewidth(0.8));
pair u=unit(G-C), v=unit(H-C);
draw(C+1.0*u--C+1.0*u+1.0*v--C+1.0*v);
dot(A);dot(B);dot(C);dot(D);dot(pE);dot(F);dot(G);dot(H);
label("$A$",A,NW);label("$B$",B,N);label("$C$",C,E);label("$D$",D,SE);label("$E$",pE,SW);label("$F$",F,NW);
label("$G$",G,N);label("$H$",H,SW);
label("$12$",(F+C)/2+(0,0.1),N);
label("$60^\circ$",F,3.2*dir(28));
\end{asy}

Place the square with $A=(0,0)$, $B=(2,0)$, $C=(2,2)$, $D=(0,2)$. Then $M=(2,1)$ and the centre of the inscribed circle is the centre of the square, $O=(1,1)$.

The triangle $AOM$ has area
\[\dfrac12\left|x_O\,y_M-x_M\,y_O\right|=\dfrac12\left|1\cdot1-2\cdot1\right|=\dfrac12,\]
and $AM=\sqrt{2^2+1^2}=\sqrt5$. The distance $d$ from $O$ to line $AM$ is the height of this triangle on base $AM$, so
\[d=\dfrac{2\cdot\dfrac12}{\sqrt5}=\dfrac{1}{\sqrt5}=\boxed{\dfrac{\sqrt5}{5}}.\]
(The foot of the perpendicular is $\left(\dfrac65,\dfrac35\right)$, which lies on segment $AM$, so this is also the distance from $O$ to the segment.)

\begin{asy}
