label("$O$",Oc,N,red); label("$R=\dfrac{17}{2}$",(Oc+B)/2,N,red);
label("$I$",I,N,blue); label("$r=3$",(3,1.5),E,blue);
\end{asy}

\textbf{Area of one patch.} Let the sphere have centre $O$ and radius $R$, let the patch have centre $P$, and let $Q$ be a point on its rim, so $PQ=\rho$. The patch is a spherical cap; let $h$ be its height, measured along $OP$ from $P$ to the plane of the rim. In the cross-section through $O$, $P$ and $Q$, the point $Q$ is at distance $R-h$ from $O$ along $OP$ and at distance $\sqrt{R^2-(R-h)^2}$ from line $OP$, so
\[\rho^2=h^2+R^2-(R-h)^2=2Rh,\qquad h=\dfrac{\rho^2}{2R}.\]
By Archimedes' formula, a cap of height $h$ on a sphere of radius $R$ has area $2\pi Rh$, so the patch has area
\[2\pi R\cdot\dfrac{\rho^2}{2R}=\pi\rho^2.\]
(The cap has exactly the area of a flat disc of radius $\rho$.)

\begin{asy}
usepackage("amsmath");
