draw(circle(O,R),linewidth(0.8));
real t=degrees(atan2(Q.y,Q.x));
draw(arc(O,R,t,180-t),blue+linewidth(2.5));
draw(Qp--Q,dashed);
draw(O--Q,gray); draw(O--P,gray);
draw(P--Q,red+linewidth(0.9));
