dot(I);
label("$A=\dfrac32$",(0,0.75),W,fontsize(8pt)); label("$B=2$",(1,0),S,fontsize(8pt)); label("$C=\dfrac52$",(1,0.75),NE,fontsize(8pt));
label("$\dfrac12$",(0.5,0.25),E,blue+fontsize(7pt));
\end{asy}

\textbf{(b)} If $A^2+B^2=C^2$ with integers $A,B,C$, then
\[(A+B)^2-C^2=2AB\]
is even. So $(A+B)^2$ and $C^2$ have the same parity, hence $A+B$ and $C$ have the same parity, and $A+B-C$ is even. It cannot equal $1$. $\blacksquare$

question:
\begin{enumerate}
\item[(a)] For each real number $k$, find the distance from the origin to the closest point of the parabola $y=x^2+k$.
\item[(b)] In particular, find this distance for $y=x^2-4$, and the closest points.
\end{enumerate}

solution:
\textbf{(a)} The squared distance from the origin to the point $\left(x,x^2+k\right)$ is
\[x^2+\left(x^2+k\right)^2=u^2+(2k+1)u+k^2,\qquad u=x^2\ge0.\]
This is a quadratic $g(u)$ in $u$ whose graph has its vertex at $u_0=-\dfrac{2k+1}{2}$.
\begin{itemize}
\item If $k\ge-\dfrac12$, then $u_0\le0$, so $g$ is increasing for $u\ge0$ and its minimum on $u\ge0$ is $g(0)=k^2$: the closest point is the vertex $(0,k)$, at distance $|k|$.
\item If $k<-\dfrac12$, then $u_0>0$ and the minimum is
\[g(u_0)=k^2-\dfrac{(2k+1)^2}{4}=-k-\dfrac14,\]
attained at $x=\pm\sqrt{u_0}$: two closest points, at distance $\sqrt{-k-\dfrac14}$.
\end{itemize}
So the distance is
\[\boxed{|k|\ \text{ if }k\ge-\dfrac12,\qquad\sqrt{-k-\dfrac14}\ \text{ if }k<-\dfrac12}\]
(the two formulas agree at $k=-\dfrac12$).

\textbf{(b)} For $k=-4$: $u_0=\dfrac72$, and the distance is $\sqrt{4-\dfrac14}=\boxed{\dfrac{\sqrt{15}}{2}}$, attained at $\left(\pm\sqrt{\dfrac72},\,-\dfrac12\right)$. Note that this is less than the distance $4$ to the vertex $(0,-4)$.

\begin{asy}
usepackage("amsmath");
size(5.5cm);
defaultpen(fontsize(10pt));
import graph;
real f(real x){return x^2-4;}
draw((-3,0)--(3,0),Arrow(6)); draw((0,-4.6)--(0,3.2),Arrow(6));
label("$x$",(3,0),E); label("$y$",(0,3.2),N);
draw(graph(f,-2.6,2.6),blue+linewidth(0.9));
real r=sqrt(15)/2, x0=sqrt(3.5);
draw(circle((0,0),r),dashed);
pair P1=(x0,f(x0)),P2=(-x0,f(x0));
draw((0,0)--P1,red); draw((0,0)--P2,red);
dot(P1); dot(P2); dot((0,-4));
label("$\left(\sqrt{\dfrac72},-\dfrac12\right)$",P1,SE,fontsize(7pt));
label("$(0,-4)$",(0,-4),SE,fontsize(7pt));
label("$y=x^2-4$",(2.6,f(2.6)),E,blue+fontsize(8pt));
\end{asy}

(For a general parabola $y=a(x-h)^2+k$ the same method, minimising $x^2+y^2$, leads to a cubic equation for the $x$-coordinate of the closest point; it simplifies as above when the axis of the parabola passes through the origin.)

question:
A set $A$ is a \emph{subset} of a set $B$ if every element of $A$ is also an element of $B$ (the empty set and $B$ itself count).
\begin{enumerate}
\item[(a)] How many subsets does the set $\{1,5,6,23,24\}$ have?
\item[(b)] How many of these subsets contain both $23$ and $24$?
\end{enumerate}

Let $f(x)=ax^2+bx+c$ with $a\ne0$, and let $h=-\dfrac{b}{2a}$.
\begin{enumerate}
\item[(a)] Prove that $f(h+t)=f(h-t)$ for every real $t$, so that the graph of $f$ is symmetric about the line $x=h$.
\item[(b)] Rewrite $f$ in vertex form by completing the square, and explain how the axis of symmetry can be read off from it.
\item[(c)] Find the axis of symmetry and the vertex of $y=2x^2-12x+7$ in both ways.
\end{enumerate}

solution:
\textbf{(a)} Using $b=-2ah$,
\[f(h\pm t)=a\left(h^2\pm2ht+t^2\right)+b(h\pm t)+c=\left(ah^2+bh+c+at^2\right)\pm t(2ah+b)=ah^2+bh+c+at^2,\]
since $2ah+b=0$. The two values are equal, so the points of the graph at $x=h+t$ and $x=h-t$ have the same height and are mirror images in the line $x=h$. $\blacksquare$

\textbf{(b)} Completing the square,
\[f(x)=a\left(x^2+\dfrac bax\right)+c=a\left(x+\dfrac{b}{2a}\right)^2+c-\dfrac{b^2}{4a}=a(x-h)^2+k,\qquad k=c-\dfrac{b^2}{4a}.\]
In vertex form $a(x-h)^2+k$ the value depends only on $(x-h)^2$, which is the same at $h+t$ and $h-t$; so the axis is $x=h$, read off directly, and the vertex is $(h,k)$.

\textbf{(c)} With $a=2$, $b=-12$: $h=-\dfrac{-12}{4}=3$. Completing the square, $2x^2-12x+7=2(x-3)^2-11$. Both ways the axis of symmetry is $\boxed{x=3}$, and the vertex is $\boxed{(3,-11)}$.

\begin{asy}
usepackage("amsmath");
size(5.5cm);
defaultpen(fontsize(10pt));
import graph;
real q=0.35;
real f(real x){return 2x^2-12x+7;}
pair T(real x,real y){return (x,q*y);}
draw(T(-0.6,0)--T(6.8,0),Arrow(6)); draw(T(0,-12.5)--T(0,8.5),Arrow(6));
label("$x$",T(6.8,0),E); label("$y$",T(0,8.5),N);
guide g; for(int i=0;i<=60;++i){real x=0.15+5.7*i/60; g=g--T(x,f(x));}
draw(g,blue+linewidth(0.9));
draw(T(3,-12.5)--T(3,8),red+dashed);
dot(T(3,-11)); label("$(3,-11)$",T(3,-11),SE,fontsize(8pt));
real t=1.7; dot(T(3-t,f(3-t))); dot(T(3+t,f(3+t))); draw(T(3-t,f(3-t))--T(3+t,f(3+t)),dotted);
label("$x=3$",T(3,8),N,red+fontsize(8pt)); label("$y=2x^2-12x+7$",T(5.85,f(5.85)),E,blue+fontsize(8pt));
\end{asy}

Number the squares $0,1,2,\dots$, square $k$ having side $\dfrac1{2^k}$ and area $\dfrac1{4^k}$. Square $k$ ($k\ge1$) is bisected by the top side of square $k-1$: its lower half lies inside square $k-1$, and its upper half lies above the top side of square $k-1$. The top sides of the squares get higher and higher, so the top side of square $k-1$ is the highest point of squares $0,1,\dots,k-1$; hence the upper half of square $k$ does not overlap any earlier square. So each new square adds exactly half its area:
\[1+\dfrac12\left(\dfrac14+\dfrac1{16}+\dfrac1{64}+\cdots\right)=1+\dfrac12\cdot\dfrac{\dfrac14}{1-\dfrac14}=1+\dfrac12\cdot\dfrac13=\boxed{\dfrac76}.\]

\begin{asy}
usepackage("amsmath");
size(3.5cm);
defaultpen(fontsize(10pt));
real y=0, s=1; real c=0.5;
fill(box((0,0),(1,1)),rgb(0.85,0.85,0.85));
for(int k=1;k<=6;++k){
  real t=s/2; real top=y+s;
  fill(box((c-t/2,top),(c+t/2,top+t/2)),rgb(0.8,0.88,1));
  draw(box((c-t/2,top-t/2),(c+t/2,top+t/2)));
  y=top-t/2; s=t;
}
draw(box((0,0),(1,1)),linewidth(0.8));
label("$1$",(0.5,0),S);
draw((0.24,1.1)--(-0.05,1.1),gray); label("$\dfrac12$",(-0.05,1.1),W,fontsize(8pt));
draw((0.63,1.3)--(1.0,1.33),gray); label("$\dfrac14$",(1.0,1.33),E,fontsize(8pt));
\end{asy}

(A common mistake is to treat the added areas $\dfrac18,\dfrac1{32},\dfrac1{128},\dots$ as having ratio $\dfrac18$, which gives $1+\dfrac{\dfrac18}{1-\dfrac18}=\dfrac87$; the ratio is $\dfrac14$, because each square has a quarter of the area of the previous one.)

question:
For a real number $x\ge0$, the square root $\sqrt x$ is defined as the real number $y\ge0$ such that $y^2=x$.
\begin{enumerate}
\item[(a)] Prove that for every $x\ge0$ there is exactly one real number $y\ge0$ with $y^2=x$ (for existence you may use the intermediate value theorem). Conclude that $\sqrt{\phantom{x}}$ is a function on $[0,\infty)$ whose values are never negative.
\item[(b)] Solve $y^2=4$, and explain why this does not mean that $\sqrt4=\pm2$.
\end{enumerate}

solution:
For fixed $x$ and $y$ with $3x+2y\le26$, $z$ can be any of $0,1,\dots,26-3x-2y$: that is $27-3x-2y$ values. Put $m=26-3x$ ($x=0,1,\dots,8$). Summing over $y=0,1,\dots,\left\lfloor\dfrac m2\right\rfloor$:
\begin{itemize}
\item if $m=2t$ is even: $\displaystyle\sum_{y=0}^{t}(2t+1-2y)=1+3+\cdots+(2t+1)=(t+1)^2$;
\item if $m=2t+1$ is odd: $\displaystyle\sum_{y=0}^{t}(2t+2-2y)=2+4+\cdots+(2t+2)=(t+1)(t+2)$.
\end{itemize}
So the counts for $x=0,1,\dots,8$ ($m=26,23,20,17,14,11,8,5,2$) are
\[196,\ 156,\ 121,\ 90,\ 64,\ 42,\ 25,\ 12,\ 4,\]
and the total is $\boxed{710}$.

The cylinder with radius $k$ and height $(23-k)^2$ has volume $\pi k^2(23-k)^2$.

\begin{asy}
usepackage("amsmath");
size(3.5cm);
defaultpen(fontsize(10pt));
real r=1.3, h=2.4, e=0.32;
path fr=shift(0,0)*xscale(r)*yscale(e*r)*arc((0,0),1,180,360);
path bk=xscale(r)*yscale(e*r)*arc((0,0),1,0,180);
fill(xscale(r)*yscale(e*r)*unitcircle,white);
draw(shift(0,h)*xscale(r)*yscale(e*r)*unitcircle,linewidth(0.8));
draw(fr,linewidth(0.8)); draw(bk,dashed);
draw((-r,0)--(-r,h),linewidth(0.8)); draw((r,0)--(r,h),linewidth(0.8));
dot((0,h)); draw((0,h)--(r,h),blue); label("$k$",(r/2,h+e*r),N,blue);
draw((r+0.25,0)--(r+0.25,h),red,Arrows(4)); label("$(23-k)^2$",(r+0.25,h/2),E,red);
\end{asy}

So the total volume is $\pi T$ with
\[T=\sum_{k=1}^{22}k^2(23-k)^2=\sum_{k=1}^{22}\left(23k-k^2\right)^2=529\sum_{k=1}^{22}k^2-46\sum_{k=1}^{22}k^3+\sum_{k=1}^{22}k^4.\]
With $n=22$:
\begin{align*}
\sum k^2&=\dfrac{n(n+1)(2n+1)}{6}=\dfrac{22\cdot23\cdot45}{6}=3795,\\
\sum k^3&=\left(\dfrac{n(n+1)}{2}\right)^2=253^2=64009,\\
\sum k^4&=\dfrac{n(n+1)(2n+1)\left(3n^2+3n-1\right)}{30}=\dfrac{22\cdot23\cdot45\cdot1517}{30}=1151403.
\end{align*}
Hence
\[T=529\cdot3795-46\cdot64009+1151403=2007555-2944414+1151403=214544,\]
and the volume of the cake is $\boxed{214544\pi}$.

Use coordinates $A=(-15,0)$, $B=(15,0)$, $C=(10,12)$, $D=(-10,12)$. The trapezoid has area $\dfrac{30+20}{2}\cdot12=300$.

\textbf{The circumcentre.} An isosceles trapezoid is cyclic. Its circumcentre $O=(0,k)$ lies on the axis of symmetry, and $OA=OD$ gives
\[15^2+k^2=10^2+(12-k)^2\iff24k=19\iff k=\dfrac{19}{24}.\]
The perpendicular bisectors of $AB$, $AC$ and $AD$ all pass through $O$.

\textbf{The zone.} Let $M=(0,0)$ be the midpoint of $AB$ and $N=\left(-\dfrac{25}{2},6\right)$ the midpoint of $AD$. The points closer to $A$ than to $B$ are those with $x<0$, on $A$'s side of the line $MO$; the points closer to $A$ than to $D$ are those on $A$'s side of the perpendicular bisector $NO$ of $AD$. Inside the trapezoid these two conditions cut out the quadrilateral $AMON$. Every vertex of $AMON$ is at least as close to $A$ as to $C$:
\[MA=15<\sqrt{244}=MC,\qquad OA=OC,\qquad NA=\dfrac{13}{2}<\sqrt{\left(\dfrac{45}{2}\right)^2+6^2}=NC,\]
and the set of points closer to $A$ than to $C$ is a half-plane, which is convex, so it contains $AMON$ (up to the boundary point $O$). Hence the danger zone is the quadrilateral $AMON$ (boundaries have zero area).

\begin{asy}
usepackage("amsmath");
size(7cm);
defaultpen(fontsize(10pt));
real s=0.2;
pair A=s*(-15,0), B=s*(15,0), C=s*(10,12), D=s*(-10,12);
pair O=s*(0,19/24), M=s*(0,0), Nn=s*(-12.5,6);
fill(A--M--O--Nn--cycle,rgb(1,0.85,0.5));
draw(A--B--C--D--cycle,linewidth(0.9));
draw(M--s*(0,12),dashed);
pair u=unit(rotate(90)*(D-A));
draw(Nn--O,dashed);
dot(O); dot(M); dot(Nn);
label("$A$",A,SW); label("$B$",B,SE); label("$C$",C,NE); label("$D$",D,NW);
label("$O$",O,NE); label("$M$",M,S); label("$N$",Nn,W);
label("$30$",(A+B)/2+s*(7.5,0),S); label("$20$",(C+D)/2+s*(5,0),N);
draw(s*(17,0)--s*(17,12),Arrows(4)); label("$12$",s*(17,6),E);
\end{asy}

\textbf{Its area.} Triangle $AMO$ has legs $AM=15$ and $MO=\dfrac{19}{24}$, so its area is $\dfrac12\cdot15\cdot\dfrac{19}{24}=\dfrac{95}{16}$. Triangle $ANO$ has a right angle at $N$, with $AN=\dfrac{AD}{2}=\dfrac{13}{2}$ (as $AD=\sqrt{5^2+12^2}=13$) and
\[ON^2=OA^2-AN^2=\left(225+\dfrac{361}{576}\right)-\dfrac{169}{4}=\dfrac{105625}{576},\qquad ON=\dfrac{325}{24},\]
so its area is $\dfrac12\cdot\dfrac{13}{2}\cdot\dfrac{325}{24}=\dfrac{4225}{96}$. The danger zone has area $\dfrac{570}{96}+\dfrac{4225}{96}=\dfrac{4795}{96}$, which is
\[\dfrac{4795}{96\cdot300}=\dfrac{959}{5760}\quad\text{of the trapezoid, i.e.}\quad\boxed{\dfrac{4795}{288}\%\approx16.65\%}.\]

\textbf{Key fact (British flag theorem).} For any point $X$ and any rectangle $ABCD$, $XA^2+XC^2=XB^2+XD^2$. Indeed, take coordinates $A=(0,0)$, $B=(w,0)$, $C=(w,h)$, $D=(0,h)$ and $X=(x,y)$. Then
\begin{align*}
XA^2+XC^2&=x^2+y^2+(x-w)^2+(y-h)^2,\\
XB^2+XD^2&=(x-w)^2+y^2+x^2+(y-h)^2,
\end{align*}
and the two sums are equal.

Hence $XD^2=XA^2+XC^2-XB^2=9+49-25=33$, and Ash is $\boxed{\sqrt{33}}$ from corner $D$.

Such a room exists: with $X$ at the origin, $A=\left(-\sqrt5,-2\right)$, $B=\left(\sqrt{21},-2\right)$, $C=\left(\sqrt{21},\sqrt{28}\right)$, $D=\left(-\sqrt5,\sqrt{28}\right)$ gives $XA=3$, $XB=5$, $XC=7$.

