dot(D); dot(H);
label("$A$",A,N); label("$B$",B,SW); label("$C$",C,SE); label("$D$",D,S); label("$H$",H,S);
label("$c$",(A+B)/2,NW); label("$b$",(A+C)/2,NE); label("$d$",(A+D)/2+(0.1,0),E,blue); label("$h$",(A+H)/2,W);
draw((0,-0.75)--(3,-0.75),Arrows(4)); draw((3,-0.75)--(7,-0.75),Arrows(4));
label("$m$",(1.5,-0.75),S); label("$n$",(5,-0.75),S);
\end{asy}

By the distance formula,
\[c^2=p^2+h^2,\qquad b^2=(a-p)^2+h^2,\qquad d^2=(p-m)^2+h^2.\]
Then, using $m+n=a$,
\begin{align*}
b^2m+c^2n&=m\left(a^2-2ap+p^2+h^2\right)+n\left(p^2+h^2\right)\\
&=(m+n)\left(p^2+h^2\right)+ma^2-2amp=a\left(p^2+h^2\right)+ma^2-2amp,
\end{align*}
and
\begin{align*}
a\left(d^2+mn\right)&=a\left(p^2-2pm+m^2+h^2+mn\right)=a\left(p^2+h^2\right)-2amp+am(m+n)\\
&=a\left(p^2+h^2\right)-2amp+a^2m.
\end{align*}
The two expressions are equal. $\blacksquare$

Give each unit cube coordinates $(x,y,z)$ with $x,y,z\in\{1,2,\dots,n\}$. A unit cube has a face on the left or right face of the large cube exactly when $x=1$ or $x=n$, and then exactly one such face, because $1\ne n$ when $n\ge2$; similarly for $y$ and $z$. Call a coordinate \emph{extreme} if it is $1$ or $n$. Then the number of faces of a unit cube on the surface equals the number of its extreme coordinates.

Each coordinate is extreme in $2$ ways and not extreme in $n-2$ ways. A unit cube with exactly $k$ extreme coordinates is chosen by picking which $k$ coordinates are extreme, $\dbinom3k$ ways, and their values, $2^k(n-2)^{3-k}$ ways:
\begin{itemize}
\item $k=3$: $2^3=8$ (the corners);
\item $k=2$: $3\cdot4(n-2)=12(n-2)$ (along the $12$ edges);
\item $k=1$: $3\cdot2(n-2)^2=6(n-2)^2$ (on the $6$ faces);
\item $k=0$: $(n-2)^3$ (the inside).
\end{itemize}
By the binomial theorem the total is $\sum_{k=0}^3\dbinom3k2^k(n-2)^{3-k}=(2+(n-2))^3=n^3$, as it must be. $\blacksquare$

