real[] ext={100,12,12,100,12,12,100,12};
real[] len={1.39554145,1,1,1,1,1,1,1.39554145};
pair[] V; pair p=(0,0); real h=0;
for(int k=0;k<8;++k){V.push(p); p+=len[k]*dir(h); h+=ext[k];}
draw(V[0]--V[1]--V[2]--V[3]--V[4]--V[5]--V[6]--V[7]--cycle,linewidth(0.9));
for(int k=0;k<8;++k) dot(V[k]);
pair c=(V[0]+V[1]+V[2]+V[3]+V[4]+V[5]+V[6]+V[7])/8;
for(int k=0;k<8;++k){
  real e=ext[(k+7)%8];
  if(e>90){ pair a=V[(k+7)%8], q=V[(k+1)%8];
    real a1=degrees(q-V[k]); draw(arc(V[k],0.25,a1,a1+180-e),red);
    label("$80^\circ$",V[k]+0.5*unit(c-V[k]),red+fontsize(8pt)); }
  else label("$168^\circ$",V[k]+0.32*unit(c-V[k]),fontsize(7pt));
}
\end{asy}

So the answer is $\boxed{\textbf{(A)}\ 3}$.

