real t=110;
pair O=(0,0), A=dir(0), B=dir(t), C=sqrt(2)*dir(250);
pair u=unit(B-A), v=rotate(90)*u;
draw(circle(O,1),linewidth(0.8)); draw(circle(O,sqrt(2)),linewidth(0.8));
// far arcs (where the angle at A or at B is obtuse)
real s1=-dot(A,v)+sqrt(dot(A,v)^2+1), s2=-dot(A,v)-sqrt(dot(A,v)^2+1);
pair P1=A+s1*v, P2=A+s2*v;
real a1=degrees(P1), a2=degrees(P2);
path arcA=arc(O,sqrt(2),a1,a2,CCW); if(dot(relpoint(arcA,0.5)-A,u)>0) arcA=arc(O,sqrt(2),a1,a2,CW);
draw(arcA,red+linewidth(2));
draw(P1--P2,red+dashed);
real r1=-dot(B,v)+sqrt(dot(B,v)^2+1), r2=-dot(B,v)-sqrt(dot(B,v)^2+1);
pair Q1=B+r1*v, Q2=B+r2*v;
real b1=degrees(Q1), b2=degrees(Q2);
path arcB=arc(O,sqrt(2),b1,b2,CCW); if(dot(relpoint(arcB,0.5)-B,-u)>0) arcB=arc(O,sqrt(2),b1,b2,CW);
draw(arcB,deepgreen+linewidth(2));
draw(Q1--Q2,deepgreen+dashed);
draw(circle((A+B)/2,abs(B-A)/2),gray+dotted);
