label("$O$",O,S); label("$A$",A,E); label("$B$",B,N); label("$C$",C,S);
pair LA=(P1.y<P2.y)?P1:P2; pair LB=(Q1.y<Q2.y)?Q1:Q2;
label("$\ell_A$",A+0.5*(LA-A)+0.12*dir(degrees(LA-A)+90),dir(degrees(LA-A)+90),red); label("$\ell_B$",B+0.6*(LB-B),dir(degrees(LB-B)-90),deepgreen);
