defaultpen(fontsize(10pt));
pair P=(0.45,0.15);
path c2=circle(P,1);
real ph=degrees(P), al=degrees(acos(length(P)/2));
fill(arc((0,0),1,ph-al,ph+al)--arc(P,1,ph+180-al,ph+180+al)--cycle,rgb(0.85,0.92,1));
draw(circle((0,0),1),linewidth(0.9));
