real e=9/5, k=12/5;
pair A=p(0,0,0), B=p(5,0,0), Ep=p(e,0,0), C=p(e,-k,0), D=p(e,0,k);
draw(A--B,linewidth(0.9)); draw(A--C--B,linewidth(0.9)); draw(A--D--B,linewidth(0.9)); draw(C--D,linewidth(0.9));
draw(C--Ep,dashed+blue); draw(D--Ep,dashed+blue);
