defaultpen(fontsize(10pt));
pair A=(0,0), B=(224,0), C=(105,120), D=(35,120), O=(80,60);
pair X=(80,0), Z=(80,120), Wp=A+(80/125)*(D-A), Y=B+(144/169)*(C-B);
draw(circle(O,60),blue);
draw(A--B--C--D--cycle,linewidth(0.9));
draw(A--O--D,dashed+gray(0.4)); draw(O--Wp,red); draw(O--X,red);
pair u=unit(A-O), v=unit(D-O); draw(O+8*u--O+8*u+8*v--O+8*v,gray(0.4));
dot(A); dot(B); dot(C); dot(D); dot(O); dot(X); dot(Z); dot(Wp); dot(Y);
label("$A$",A,SW); label("$B$",B,SE); label("$C$",C,NE); label("$D$",D,NW); label("$O$",O,E);
label("$X$",X,S); label("$Z$",Z,N); label("$W$",Wp,W); label("$Y$",Y,NE);
label("$r=60$",(O+X)/2,E,red+fontsize(8pt));
label("$80$",(40,0),S,fontsize(8pt)); label("$144$",(152,0),S,fontsize(8pt));
label("$45$",(57,120),N,fontsize(8pt)); label("$25$",(93,120),N,fontsize(8pt));
\end{asy}

\textbf{Solving.} From $5tp=9tq$ we get $5p=9q$, that is, $5(125-5t)=9(169-9t)$, so $625-25t=1521-81t$, $56t=896$ and $t=16$. Hence
\[AX=80,\quad BX=144,\quad p=45,\quad q=25,\quad r^2=80\cdot45=3600=144\cdot25,\quad r=60.\]
The height of the trapezoid is the diameter $2r=120$, and the bases are $AB=80+144=224$ and $CD=45+25=70$. So
\[[ABCD]=\dfrac{224+70}{2}\cdot120=\boxed{17640}.\]
(Check: the legs have horizontal projections $\sqrt{125^2-120^2}=35$ and $\sqrt{169^2-120^2}=119$, and $35+119=154=224-70$.)

Since the identity holds for every $x$, substitute values of $x$ that make two of the three terms vanish:
\begin{itemize}
\item $x=1$: $c\cdot3\cdot2=18$, so $c=3$;
\item $x=-2$: $b\cdot(-3)(-1)=0$, so $b=0$;
\item $x=-1$: $a\cdot(-2)\cdot1=6$, so $a=-3$.
\end{itemize}
These values are necessary; conversely they work, since
\[-3(x^2+x-2)+3(x^2+3x+2)=-3x^2-3x+6+3x^2+9x+6=6x+12\]
for all $x$. (The $x^2$ terms cancel because $a+b+c=0$.) The triple is $\boxed{(a,b,c)=(-3,0,3)}$.

The container consists of two circular discs of radius $r=5$ and a curved side, which unrolls into a rectangle of height $h=34$ and width equal to the circumference $2\pi r=10\pi$.

\begin{asy}
