solution:
Let the border have width $w$ inches. Then the photo is a $(11-2w)$ by $(13-2w)$ rectangle.

\begin{asy}
usepackage("amsmath");
size(4.5cm);
defaultpen(fontsize(10pt));
real w=1.5;
filldraw(box((0,0),(11,13)),rgb(0.93,0.93,0.93),linewidth(0.9));
filldraw(box((w,w),(11-w,13-w)),rgb(0.85,0.92,1),linewidth(0.9));
label("photo, area $80$",(5.5,8));
draw((0,13.6)--(11,13.6),Arrows(5)); label("$11$",(5.5,13.6),N);
draw((11.6,0)--(11.6,13),Arrows(5)); label("$13$",(11.6,6.5),E);
