defaultpen(fontsize(10pt));
pair A=(0,0), B=(7,0), C=(2,5.5);
pair D=A+2/5*(B-A), Ep=B+2/5*(C-B), F=C+2/5*(A-C);
pair P1=extension(A,Ep,B,F), P2=extension(B,F,C,D), P3=extension(C,D,A,Ep);
fill(P1--P2--P3--cycle,rgb(0.85,0.92,1));
draw(A--B--C--cycle,linewidth(0.9)); draw(A--Ep); draw(B--F); draw(C--D);
dot(D); dot(Ep); dot(F);
label("$A$",A,SW); label("$B$",B,SE); label("$C$",C,N); label("$D$",D,S); label("$E$",Ep,NE); label("$F$",F,W);
label("$2$",(A+D)/2,S,fontsize(8pt)); label("$3$",(D+B)/2,S,fontsize(8pt));
label("$2$",(B+Ep)/2,NE,fontsize(8pt)); label("$3$",(Ep+C)/2,NE,fontsize(8pt));
label("$2$",(C+F)/2,W,fontsize(8pt)); label("$3$",(F+A)/2,W,fontsize(8pt));
\end{asy}

By the shoelace formula, the small triangle has area
\[\dfrac{1}{2\cdot19^2}\left|45(45-20)+20(20-30)+30(30-45)\right|=\dfrac{475}{722}=\dfrac{25}{38}.\]
The ratio is
\[\dfrac{\dfrac{25}{2}}{\dfrac{25}{38}}=\boxed{19}\]
(that is, $\dfrac mn=\dfrac{19}{1}$). This agrees with Routh's theorem: for the ratio $r=\dfrac23$ on all three sides, the small triangle is $\dfrac{(1-r)^2}{1+r+r^2}=\dfrac{\dfrac19}{\dfrac{19}9}=\dfrac1{19}$ of the whole.

question:
\begin{enumerate}
\item[(a)] Prove that for all positive integers $n>1$ and $k$, the number $n^k-1$ is divisible by $n-1$.
\item[(b)] Prove that for all positive integers $n$, $k$ and $m$ with $n\ne k$, the number $n^m-k^m$ is divisible by $n-k$.
\end{enumerate}

Let
\[N=115792089237316195423570985008687907852837564279074904382605163141518161494336.\]
\begin{enumerate}
\item[(a)] Find the remainder when $N$ is divided by $7$, without a computer.
\item[(b)] Find the remainder when $N^N$ is divided by $7$.
\end{enumerate}

solution:
Let the angles be $A=2B$ and $C$, with $|A-C|=20^\circ$ and $A+B+C=180^\circ$.
\begin{itemize}
\item If $C=A-20^\circ=2B-20^\circ$: $2B+B+2B-20^\circ=180^\circ$, so $B=40^\circ$, $A=80^\circ$, $C=60^\circ$. The greatest angle is $80^\circ$.
\item If $C=A+20^\circ=2B+20^\circ$: $5B+20^\circ=180^\circ$, so $B=32^\circ$, $A=64^\circ$, $C=84^\circ$. The greatest angle is $84^\circ$.
\end{itemize}
Both triangles exist (all angles positive, sum $180^\circ$).

\begin{asy}
usepackage("amsmath");
size(7cm);
defaultpen(fontsize(10pt));
void tr(pair o, real a, real b, string la, string lb, string lc){
 real c=180-a-b; real s=4; pair P=o, Q=o+(s,0);
 pair R=P+(s*Sin(b)/Sin(c))*dir(a);
 draw(P--Q--R--cycle,linewidth(0.9));
 label(la,P+0.7*dir(a/2),fontsize(8pt)); label(lb,Q+0.75*dir(180-b/2),fontsize(8pt)); label(lc,R+0.75*dir(270+(a-b)/2),fontsize(8pt));}
tr((0,0),80,40,"$80^\circ$","$40^\circ$","$60^\circ$");
tr((5.5,0),64,32,"$64^\circ$","$32^\circ$","$84^\circ$");
label("$C=A-20^\circ$",(2,-0.3),S); label("$C=A+20^\circ$",(7.5,-0.3),S);
\end{asy}

So the greatest angle is $\boxed{80^\circ\text{ or }84^\circ}$.

A cube has $12$ edges.

