draw(box((0,0),(s,s)),linewidth(0.9)); draw((0,s)--(0,s)+d--(s,s)+d--(s,s),linewidth(0.9)); draw((s,0)--(s,0)+d--(s,s)+d,linewidth(0.9));
draw((0,0)--d--(0,s)+d,dashed); draw(d--(s,0)+d,dashed);
label("$10$ in",(s/2,0),S,fontsize(8pt)); label("$12$ edges",(s/2,s)+d,N,fontsize(8pt));
