defaultpen(fontsize(10pt));
pair O=(0,0);
pair A=dir(100), B=dir(215), C=dir(325);
real a=abs(B-C), bb=abs(C-A), c=abs(A-B);
pair I=(a*A+bb*B+c*C)/(a+bb+c);
pair F=A+dot(I-A,B-A)/dot(B-A,B-A)*(B-A);
real r=abs(I-F);
pair M=dir(270);
pair u=unit(I-O); pair X=u, Y=-u;
draw(circle(O,1),gray);
draw(circle(I,r),heavygreen);
draw(A--B--C--cycle,linewidth(1));
draw(A--M,blue); draw(M--B,blue);
draw(I--F,heavygreen);
draw(X--Y,dashed+red);
dot(O); dot(I); dot(M,blue); dot(F,heavygreen);
label("$A$",A,N); label("$B$",B,SW); label("$C$",C,SE);
label("$O$",O,SE); label("$I$",I,W); label("$M$",M,S,blue); label("$F$",F,NW,heavygreen);
label("$r$",(I+F)/2,NE,heavygreen+fontsize(8pt));
dot(X,red); dot(Y,red); label("$X$",X,dir(X),red); label("$Y$",Y,dir(Y),red);
\end{asy}

\textbf{Step 1: $MB=MI$.} The inscribed angles $\angle MBC$ and $\angle MAC$ stand on the same arc $MC$, so $\angle MBC=\angle MAC=\dfrac A2$. Hence $\angle MBI=\angle MBC+\angle CBI=\dfrac A2+\dfrac B2$. On the other hand, $\angle MIB$ is an exterior angle of triangle $ABI$, so $\angle MIB=\angle IAB+\angle IBA=\dfrac A2+\dfrac B2$. Triangle $MBI$ has two equal angles, so $MB=MI$.

\textbf{Step 2: $AI\cdot IM=2Rr$.} In the right triangle $AFI$, $\angle IAF=\dfrac A2$, so $AI=\dfrac{r}{\sin\dfrac A2}$. The chord $MB$ subtends the inscribed angle $\angle MAB=\dfrac A2$, so by the extended law of sines $MB=2R\sin\dfrac A2$. With Step 1,
\[AI\cdot IM=AI\cdot MB=\dfrac{r}{\sin\dfrac A2}\cdot2R\sin\dfrac A2=2Rr.\]

\textbf{Step 3: power of the point $I$.} The point $I$ lies inside the circumcircle. For any chord through $I$, the product of the two pieces is the same (intersecting chords). For the chord $AM$ it is $AI\cdot IM$; for the diameter $XY$ through $I$ (dashed) it is $IX\cdot IY=(R-OI)(R+OI)=R^2-OI^2$. (If $I=O$, every chord through $I$ gives $R\cdot R$.) Therefore
\[R^2-OI^2=2Rr,\qquad\text{i.e.}\qquad OI^2=R^2-2Rr.\]
Since $OI^2\ge0$, also $R\ge2r$. $\blacksquare$

Place the rhombus as $A=(4,0)$, $B=(0,2)$, $C=(-4,0)$, $D=(0,-2)$, with centre $O$ at the origin, and let the square be $PQRS$ with $P$ on $AB$, $Q$ on $BC$, $R$ on $CD$ and $S$ on $DA$.

\textbf{The square has centre $O$.} Let $Z$ be the centre of the square, the midpoint of $PR$ and of $QS$, and consider the point reflection through $Z$. It maps $P$ to $R$, so it maps line $AB$ to the line through $R$ parallel to $AB$, which is line $CD$. Likewise it maps line $BC$ to line $DA$. Hence it maps $A$, the intersection of lines $AB$ and $DA$, to the intersection of lines $CD$ and $BC$, which is $C$. So $Z$ is the midpoint of $AC$, that is, $Z=O$.

\textbf{Finding the square.} The diagonals $PR$ and $QS$ of the square are perpendicular, have equal length and meet at $O$, so $Q$ is obtained from $P$ by a quarter turn about $O$. Write $P=(p_1,p_2)$, with $p_1+2p_2=4$ and $p_1,p_2\ge0$ (side $AB$). A quarter turn takes $P$ to $(-p_2,p_1)$ or to $(p_2,-p_1)$. The second point has a nonnegative first coordinate and a nonpositive second coordinate, so it cannot lie on side $BC$ (where $x\le0\le y$) unless both coordinates are $0$, which is not on $BC$. So $Q=(-p_2,p_1)$, and $Q$ on line $BC$ ($-x+2y=4$) gives $p_2+2p_1=4$. Together with $p_1+2p_2=4$ this gives $p_1=p_2=\dfrac43$. So the square is unique, with vertices $\left(\pm\dfrac43,\pm\dfrac43\right)$.

\begin{asy}
usepackage("amsmath");
size(7cm);
defaultpen(fontsize(10pt));
pair A=(4,0), B=(0,2), C=(-4,0), D=(0,-2);
real s=4/3;
pair P=(s,s), Q=(-s,s), R=(-s,-s), S2=(s,-s);
draw(A--C,dashed+gray); draw(B--D,dashed+gray);
fill(P--Q--R--S2--cycle,paleblue);
draw(P--Q--R--S2--cycle,blue+linewidth(1));
draw(A--B--C--D--cycle,linewidth(1));
dot((0,0)); label("$O$",(0,0),SW,fontsize(9pt));
label("$A(4,0)$",A,E); label("$B(0,2)$",B,N); label("$C(-4,0)$",C,W); label("$D(0,-2)$",D,S);
dot(P,blue); dot(Q,blue); dot(R,blue); dot(S2,blue);
label("$P\left(\dfrac43,\dfrac43\right)$",P,NE,blue+fontsize(9pt));
label("$Q$",Q,NW,blue); label("$R$",R,SW,blue); label("$S$",S2,SE,blue);
\end{asy}

Its side is $\dfrac83$, and its area is
\[\left(\dfrac83\right)^2=\boxed{\dfrac{64}{9}}.\]

Write $\angle B$ for the angle of the triangle at $B$, and let $D$ be the foot of the altitude from $A$. The orthocentre $H$ lies on $AD$, and since the triangle is acute, $H$ is inside the triangle and $D$ lies between $B$ and $C$; so $\angle BAH=\angle BAD$.

\begin{asy}
usepackage("amsmath");
size(6cm);
defaultpen(fontsize(10pt));
pair B=(0,0), C=(4,0), A=(1.2,3.2);
pair O=(2,1.075);
pair H=A+B+C-2*O;
pair D=(A.x,0);
draw(circle(O,abs(A-O)),gray);
draw(A--B--C--cycle,linewidth(1));
draw(A--D,blue); draw(A--O,red); draw(O--C,red+dashed);
draw(D+(0.15,0)--D+(0.15,0.15)--D+(0,0.15),blue);
draw(arc(A,0.6,degrees(B-A),degrees(D-A)),blue); draw(arc(A,0.7,degrees(B-A),degrees(D-A)),blue);
draw(arc(A,0.6,degrees(O-A),degrees(C-A)),red); draw(arc(A,0.7,degrees(O-A),degrees(C-A)),red);
dot(O,red); dot(H,blue); dot(D,blue);
label("$A$",A,N); label("$B$",B,SW); label("$C$",C,SE);
label("$O$",O,NE,red); label("$H$",H,W,blue); label("$D$",D,S,blue);
\end{asy}

\textbf{The angle at $H$.} In the right triangle $ABD$, $\angle BAD=90^\circ-\angle B$. So $\angle BAH=90^\circ-\angle B$.

\textbf{The angle at $O$.} The central angle $\angle AOC$ stands on the arc $AC$ not containing $B$, on which the inscribed angle $\angle ABC$ also stands (the triangle is acute, so $O$ is inside it), hence $\angle AOC=2\angle B$. Triangle $AOC$ is isosceles with $OA=OC$, so
\[\angle CAO=\dfrac{180^\circ-2\angle B}{2}=90^\circ-\angle B.\]

Therefore $\angle BAH=\angle CAO$. $\blacksquare$

We need $x\ne1$.
\begin{itemize}
\item If $x>1$, multiply by $x-1>0$: $(x+1)(x-1)>8$, i.e. $x^2>9$; with $x>1$ this means $x>3$.
\item If $x<1$, multiplying by $x-1<0$ reverses the inequality: $x^2-1<8$, i.e. $-3<x<3$; with $x<1$ this means $-3<x<1$.
\end{itemize}
So the solutions are $-3<x<1$ or $x>3$. In the interval from $-5$ to $5$ (length $10$) they form the pieces $(-3,1)$ of length $4$ and $(3,5]$ of length $2$, in total $6$. The answer is $\dfrac{6}{10}=\boxed{60\%}$.

question:
Let $AC$ and $BD$ be two chords of a circle with radius $R$ that intersect at a point $P$ inside the circle.
\begin{enumerate}
\item[(a)] Prove that $AP\cdot CP=BP\cdot DP$.
\item[(b)] Suppose in addition that the chords are perpendicular. Prove that
\[AP^2+BP^2+CP^2+DP^2=4R^2.\]
\end{enumerate}

solution:
Label the points so that $A$, $B$, $C$, $D$ lie on the circle in this order.

\begin{asy}
usepackage("amsmath");
size(5.5cm);
defaultpen(fontsize(10pt));
pair O=(0,0);
pair A=(-sqrt(0.96),-0.2), C=(sqrt(0.96),-0.2), B=(0.3,sqrt(0.91)), D=(0.3,-sqrt(0.91));
pair P=(0.3,-0.2);
draw(circle(O,1),gray);
draw(A--C,linewidth(1)); draw(B--D,linewidth(1));
draw(A--B,blue); draw(C--D,red); draw(B--C,dashed);
draw(P+(0.08,0)--P+(0.08,0.08)--P+(0,0.08));
draw(O--dir(140),gray+dashed); label("$R$",0.5*dir(140)+0.06*dir(230),dir(230),gray);
dot(O); dot(P);
label("$O$",O,N); label("$P$",P,SE);
label("$A$",A,W); label("$B$",B,N); label("$C$",C,E); label("$D$",D,S);
\end{asy}

\textbf{(a)} In triangles $APB$ and $DPC$, the angles at $P$ are vertical angles, and $\angle BAC=\angle BDC$ (inscribed angles on the arc $BC$). So the triangles are similar, and $\dfrac{AP}{DP}=\dfrac{BP}{CP}$, i.e. $AP\cdot CP=BP\cdot DP$.

\textbf{(b)} Now $\angle APB=\angle CPD=90^\circ$, so by Pythagoras
\[AP^2+BP^2=AB^2,\qquad CP^2+DP^2=CD^2.\]
The chord $AB$ subtends the inscribed angle $\angle ACB$ and the chord $CD$ subtends the inscribed angle $\angle CBD$, so by the extended law of sines
\[AB=2R\sin\angle ACB,\qquad CD=2R\sin\angle CBD.\]
In triangle $PBC$ the angle at $P$ is $90^\circ$, so $\angle PCB+\angle PBC=90^\circ$, that is, $\angle ACB+\angle CBD=90^\circ$, and $\sin\angle CBD=\cos\angle ACB$. Therefore
\[AP^2+BP^2+CP^2+DP^2=AB^2+CD^2=4R^2\left(\sin^2\angle ACB+\cos^2\angle ACB\right)=4R^2.\]
$\blacksquare$

(Without the perpendicularity there is no relation between the four lengths and $R$ other than (a): keeping $AP,BP,CP,DP$ fixed and changing the angle between the chords changes $R$, unless all four lengths are equal and $P$ is the centre.)

question:
On the dart board shown, the outer circle has radius $6$ and the inner circle has radius $3$. Three radii divide each circle into three congruent regions, with point values shown. The probability that a dart hits a given region is proportional to the area of the region. When two darts hit this board, the score is the sum of the point values of the regions hit. What is the probability that the score is odd?

\begin{asy}
usepackage("amsmath");
size(4.5cm);
defaultpen(fontsize(10pt));
draw(circle((0,0),6),linewidth(1)); draw(circle((0,0),3),linewidth(1));
draw((0,0)--6*dir(90)); draw((0,0)--6*dir(210)); draw((0,0)--6*dir(330));
label("$1$",1.5*dir(150)); label("$2$",1.5*dir(30)); label("$2$",1.5*dir(270));
label("$2$",4.5*dir(150)); label("$1$",4.5*dir(30)); label("$1$",4.5*dir(270));
\end{asy}

$\textbf{(A) }\dfrac{17}{36}\qquad\textbf{(B) }\dfrac{35}{72}\qquad\textbf{(C) }\dfrac12\qquad\textbf{(D) }\dfrac{37}{72}\qquad\textbf{(E) }\dfrac{19}{36}$

solution:
The whole board has area $36\pi$. The inner circle has area $9\pi$, so each inner region has area $3\pi$; the ring has area $36\pi-9\pi=27\pi$, so each outer region has area $9\pi$. The regions worth $1$ point (shaded) are one inner region and two outer regions:

\begin{asy}
usepackage("amsmath");
size(5cm);
defaultpen(fontsize(10pt));
path sec(real r1,real r2,real a1,real a2){return arc((0,0),r2,a1,a2)--arc((0,0),r1,a2,a1)--cycle;}
fill((0,0)--arc((0,0),3,90,210)--cycle,palegreen);
fill(sec(3,6,330,450),palegreen); fill(sec(3,6,210,330),palegreen);
draw(circle((0,0),6),linewidth(1)); draw(circle((0,0),3),linewidth(1));
draw((0,0)--6*dir(90)); draw((0,0)--6*dir(210)); draw((0,0)--6*dir(330));
label("$1$",1.5*dir(150)); label("$2$",1.5*dir(30)); label("$2$",1.5*dir(270));
label("$2$",4.5*dir(150)); label("$1$",4.5*dir(30)); label("$1$",4.5*dir(270));
label("$3\pi$",1.6*dir(150)+(0,-0.8),fontsize(7pt)); label("$9\pi$",4.5*dir(30)+(0,-0.7),fontsize(8pt));
label("$9\pi$",4.5*dir(270)+(0,-0.7),fontsize(8pt));
\end{asy}

So a dart scores an odd number with probability
\[\dfrac{3\pi+9\pi+9\pi}{36\pi}=\dfrac{21}{36}=\dfrac{7}{12},\]
and an even number with probability $\dfrac{5}{12}$. The total score is odd exactly when one dart scores odd and the other even, which happens with probability
\[2\cdot\dfrac{7}{12}\cdot\dfrac{5}{12}=\dfrac{70}{144}=\boxed{\textbf{(B) }\dfrac{35}{72}}.\]

question:
Let $S=1!+2!+3!+\cdots+50!$.
\begin{enumerate}
\item[(a)] Explain why, for every prime $p\le50$, the number $S$ leaves the same remainder on division by $p$ as $1!+2!+\cdots+(p-1)!$.
\item[(b)] Which of the primes $2,3,5,7,11,13$ divide $S$?
\item[(c)] Show that $S$ is divisible by $99$.
\end{enumerate}

solution:
The factors of $N$ are $10^k-1$ for $k=1,2,\dots,999$.

\textbf{The errors.}
\begin{itemize}
\item The product is not made of $333$ repeated groups $9\cdot99\cdot999$. Only the first two factors are $9$ and $99$; every factor with $k\ge3$ nines is $10^k-1\equiv-1\pmod{1000}$, since $1000\mid10^k$. So there is one $9$, one $99$, and $997$ factors congruent to $-1$.
\item Even if there were $333$ equal groups, each congruent to $109$, their product would be congruent to $109^{333}$, not to $109\cdot333$: multiplying copies of a number gives a power, not a multiple.
\end{itemize}

\textbf{The correct remainder.}
\[N\equiv9\cdot99\cdot(-1)^{997}=-891\equiv\boxed{109}\pmod{1000}.\]

Let $ABCD$ be a trapezoid with $AB\parallel DC$ and legs $AD$ and $BC$. The bases are not equal (otherwise $ABCD$ would be a parallelogram, with two pairs of parallel sides); say $AB<DC$.

\textbf{Lemma: $AD=BC$ if and only if $\angle ADC=\angle BCD$.} Draw through $B$ the line parallel to $AD$; it meets $DC$ at $X$. Then $ABXD$ is a parallelogram, so $BX=AD$ and $DX=AB<DC$; hence $X$ lies between $D$ and $C$. Since $BX\parallel AD$, the corresponding angles give $\angle BXC=\angle ADC$.

\begin{asy}
usepackage("amsmath");
size(5cm);
defaultpen(fontsize(10pt));
pair A=dir(125), B=dir(55), D=dir(200), C=dir(340);
pair X=B+D-A;
draw(circle((0,0),1),gray);
draw(A--B--C--D--cycle,linewidth(1));
draw(B--X,dashed+blue);
label("$A$",A,NW); label("$B$",B,NE); label("$C$",C,SE); label("$D$",D,SW); label("$X$",X,S,blue);
draw(arc(D,0.18,0,degrees(A-D)),red); draw(arc(X,0.18,0,degrees(B-X)),red);
draw(arc(C,0.18,degrees(B-C),180),heavygreen);
\end{asy}

In triangle $BXC$, $BX=BC$ holds if and only if the angles opposite these sides are equal, $\angle BCX=\angle BXC$. As $BX=AD$ and $\angle BXC=\angle ADC$, this says: $AD=BC$ if and only if $\angle BCD=\angle ADC$.

\textbf{The main statement.} Because $AB\parallel DC$, the co-interior angles give $\angle DAB+\angle ADC=180^\circ$. A convex quadrilateral is cyclic if and only if a pair of opposite angles adds up to $180^\circ$. So
\[ABCD\text{ is cyclic}\iff\angle DAB+\angle BCD=180^\circ\iff\angle BCD=180^\circ-\angle DAB=\angle ADC\iff AD=BC,\]
the last step by the lemma. $\blacksquare$

(The definition matters: a parallelogram that is not a rectangle has a pair of equal opposite sides but is not cyclic.)

question:
\begin{enumerate}
\item[(a)] A cone has a circular base of radius $r$ and height $h$, and a pyramid has a square base of area $\pi r^2$ and height $h$. Both stand on the same horizontal plane. Show that every horizontal plane cuts the two solids in cross-sections of equal area, and deduce from Cavalieri's principle (two solids whose cross-sections at every height have equal areas have equal volumes) that the volume of the cone is $\dfrac13\pi r^2h$.
\item[(b)] A ball of radius $r$ is cut into thin concentric spherical shells. Using the surface area $4\pi s^2$ of a sphere of radius $s$, explain why the volume of the ball is $\displaystyle\int_0^r4\pi s^2\,ds$, and compute it. Compare with the volume of a pyramid with base area $4\pi r^2$ and height $r$.
\end{enumerate}

solution:
\textbf{(a)} Consider the plane at height $y$, with $0\le y\le h$. The part of each solid above this plane is a smaller copy of the whole solid, scaled from the apex by the factor $k=\dfrac{h-y}{h}$ (its height is $h-y$ instead of $h$). So the cross-section of the cone is a disc of radius $kr$, with area $k^2\pi r^2$, and the cross-section of the pyramid is a square similar to the base with ratio $k$, with area $k^2\cdot\pi r^2$.

\begin{asy}
usepackage("amsmath");
size(8cm);
defaultpen(fontsize(10pt));
real r=1.2, h=3, y=1.2, k=(h-y)/h;
pair T=(0,h);
draw(T--(-r,0)); draw(T--(r,0));
draw(shift(0,0)*xscale(r)*yscale(0.3)*arc((0,0),1,180,360),linewidth(0.8));
draw(shift(0,0)*xscale(r)*yscale(0.3)*arc((0,0),1,0,180),dashed);
filldraw(shift(0,y)*xscale(r*k)*yscale(0.3*k)*unitcircle,paleblue,blue);
draw((0,0)--(r,0),dashed); label("$r$",(r/2,0),S,fontsize(9pt));
real s=sqrt(pi)*r;
pair b0=(3,-0.35), b1=b0+(s,0), b2=b1+(0.7,0.7), b3=b0+(0.7,0.7);
pair Tp=(b0+b2)/2+(0,h);
draw(b0--b1--b2); draw(b2--b3--b0,dashed);
draw(Tp--b0); draw(Tp--b1); draw(Tp--b2); draw(Tp--b3,dashed);
pair c0=Tp+(b0-Tp)*k, c1=Tp+(b1-Tp)*k, c2=Tp+(b2-Tp)*k, c3=Tp+(b3-Tp)*k;
filldraw(c0--c1--c2--c3--cycle,paleblue,blue);
draw((-1.8,y)--(6.4,y),dotted+gray); draw((-1.8,0)--(6.4,0),dotted+gray);
draw((-1.6,0)--(-1.6,y),Arrows(4)); label("$y$",(-1.6,y/2),W,fontsize(9pt));
draw((6.2,0)--(6.2,h),Arrows(4)); label("$h$",(6.2,h/2),E,fontsize(9pt));
label("area $\pi r^2$",(b0+b1)/2,S,fontsize(8pt));
\end{asy}

The areas are equal at every height, so by Cavalieri's principle the two solids have the same volume. The pyramid has volume $\dfrac13(\text{base area})(\text{height})$, so
\[V_{\text{cone}}=\boxed{\dfrac13\pi r^2h}.\]

\textbf{(b)} The shell between the spheres of radii $s$ and $s+ds$ has area $4\pi s^2$ and thickness $ds$, so its volume is $4\pi s^2\,ds$ up to terms of higher order in $ds$. Adding all the shells from the centre ($s=0$) to the surface ($s=r$) and letting the thickness tend to $0$ gives
\[V_{\text{ball}}=\int_0^r4\pi s^2\,ds=\left[\dfrac{4\pi s^3}{3}\right]_0^r=\boxed{\dfrac43\pi r^3}.\]

\begin{asy}
usepackage("amsmath");
size(3.5cm);
defaultpen(fontsize(10pt));
real R=1, s=0.62, ds=0.1;
filldraw(circle((0,0),s+ds),palegreen,heavygreen); filldraw(circle((0,0),s),white,heavygreen);
draw(circle((0,0),R),linewidth(1));
draw(xscale(R)*yscale(0.3*R)*arc((0,0),1,180,360)); draw(xscale(R)*yscale(0.3*R)*arc((0,0),1,0,180),dashed);
dot((0,0)); label("$O$",(0,0),SW,fontsize(8pt));
draw((0,0)--(s*dir(70)),heavygreen); label("$s$",0.8*s*dir(70),E,heavygreen+fontsize(8pt));
draw((0,0)--(R*dir(-30)),gray); label("$r$",0.75*R*dir(-30),S,fontsize(8pt));
\end{asy}

A pyramid with base area $4\pi r^2$ and height $r$ has, at distance $s$ from its apex, a cross-section of area $4\pi r^2\left(\dfrac sr\right)^2=4\pi s^2$: exactly the area of the shell of radius $s$. So ``unwrapping'' the shells into flat layers stacks them into this pyramid, and indeed its volume is $\dfrac13\cdot4\pi r^2\cdot r=\dfrac43\pi r^3$.

Let $ABCD$ be a rectangle with diagonal $AC$, and let $\alpha=\angle BAC$, so $\angle CAD=90^\circ-\alpha$.

\begin{asy}
usepackage("amsmath");
size(5.5cm);
defaultpen(fontsize(10pt));
pair A=(0,0), B=(5,0), C=(5,3), D=(0,3);
draw(A--B--C--D--cycle,linewidth(1));
draw(A--C,blue);
draw((4.7,0)--(4.7,0.3)--(5,0.3));
draw(arc(A,0.9,0,degrees(C)),red); draw(arc(A,1.1,degrees(C),90),heavygreen);
label("$\alpha$",1.2*dir(degrees(C)/2),red+fontsize(9pt));
label("$90^\circ-\alpha$",1.15*dir(65),NE,heavygreen+fontsize(9pt));
label("$A$",A,SW); label("$B$",B,SE); label("$C$",C,NE); label("$D$",D,NW);
\end{asy}

In the right triangle $ABC$ (right angle at $B$), $\angle BCA=90^\circ-\alpha$.

\textbf{If $AC$ bisects $\angle A$}, then $\alpha=90^\circ-\alpha$, so $\alpha=45^\circ$. Then triangle $ABC$ has two angles of $45^\circ$, so it is isosceles with $AB=BC$, and the rectangle is a square.

\textbf{If $ABCD$ is a square}, then $AB=BC$, so triangle $ABC$ is isosceles and $\angle BAC=\angle BCA$. These two angles add up to $90^\circ$, so each is $45^\circ$. Hence $\angle BAC=\angle CAD=45^\circ$, and in the same way the diagonal bisects the angle at $C$.

So a diagonal bisects the angles at its endpoints exactly for squares. For a rectangle with $AB>BC$, the larger side is opposite the larger angle in triangle $ABC$, so $\angle BCA>\angle BAC$, that is, $\alpha<45^\circ$: the diagonal is closer to the longer side. $\blacksquare$

The probability is the ratio of the areas, so
\[\dfrac{\pi r^2}{25}=\dfrac12,\qquad r^2=\dfrac{25}{2\pi},\qquad r=\dfrac{5}{\sqrt{2\pi}}\approx1.995.\]

