defaultpen(fontsize(10pt));
pair O=(0,0), T=5*dir(20), F=(T.x,0);
draw((-0.6,0)--(5.6,0),linewidth(0.8));
draw(O--T,brown+linewidth(2));
draw(T--F,dashed+orange,Arrow(5));
draw(F+(-0.15,0)--F+(-0.15,0.15)--F+(0,0.15));
filldraw(circle(T,0.09),orange,orange);
draw(arc(O,0.8,0,20)); label("$20^\circ$",0.85*dir(8),E,fontsize(8pt));
