draw(A--Bp,blue+linewidth(0.9)); draw(C--D,red+linewidth(0.9));
pair X=extension(A,Bp,C,D); dot(X);
label("$1$",(A+X)/2+(-1,2.2)); label("$2$",(C+X)/2+(3,0)); label("$3$",(Bp+X)/2+(1,-3)); label("$4$",(D+X)/2+(-3,0));
