defaultpen(fontsize(10pt));
real r=1, h=2.2;
draw(xscale(r)*yscale(0.4)*arc((0,0),1,180,360),linewidth(0.9)); draw(xscale(r)*yscale(0.4)*arc((0,0),1,0,180),dashed);
draw(shift(0,h)*xscale(r)*yscale(0.4)*unitcircle,linewidth(0.9));
draw((-r,0)--(-r,h),linewidth(0.9)); draw((r,0)--(r,h),linewidth(0.9));
draw((0,h)--(r,h),blue); dot((0,h),blue); label("$r$",(r/2,h),N,blue+fontsize(9pt));
draw((1.35,0)--(1.35,h),red,Arrows(5)); label("$h$",(1.35,h/2),E,red);
label("$V=\pi r^2h$",(0,-0.55),S);
