question:
Let $ABC$ be an acute triangle, and let $D$, $E$, $F$ be the feet of the altitudes from $A$, $B$, $C$ on $BC$, $CA$, $AB$ respectively. Let $P$ be one of the two intersection points of the line $EF$ with the circumcircle of $ABC$. The lines $BP$ and $DF$ meet at the point $Q$. Prove that $AP=AQ$.
\begin{asy}
usepackage("amsmath");
size(9cm);
defaultpen(fontsize(10pt));
pair perpvec(pair v){return (-v.y,v.x);}
pair inter(pair Z1,pair Z2,pair Z3,pair Z4){
  real a1=Z2.y-Z1.y, b1=Z1.x-Z2.x, c1=a1*Z1.x+b1*Z1.y;
  real a2=Z4.y-Z3.y, b2=Z3.x-Z4.x, c2=a2*Z3.x+b2*Z3.y;
  real det=a1*b2-a2*b1;
  return ((b2*c1-b1*c2)/det,(a1*c2-a2*c1)/det);
}
pair perpfoot(pair X,pair Y,pair Z){
  return Y+(dot(X-Y,Z-Y)/dot(Z-Y,Z-Y))*(Z-Y);
}
pair A=(0,6), B=(-3,0), C=(5,0);
pair footD=perpfoot(A,B,C);
pair footE=perpfoot(B,C,A);
pair footF=perpfoot(C,A,B);
pair O=inter((A+B)/2,(A+B)/2+perpvec(B-A),(A+C)/2,(A+C)/2+perpvec(C-A));
real R=abs(O-A);
pair efv=footE-footF;
real qa=dot(efv,efv), qb=2*dot(efv,footF-O), qc=dot(footF-O,footF-O)-R*R;
real qd=sqrt(qb*qb-4*qa*qc);
pair pointP=footF+((-qb+qd)/(2*qa))*efv;
pair pointP2=footF+((-qb-qd)/(2*qa))*efv;
pair pointQ=inter(B,pointP,footD,footF);
draw(circle(O,R),linewidth(0.7));
draw(A--B--C--cycle,linewidth(0.9));
draw(A--footD,dashed+linewidth(0.6));
draw(B--footE,dashed+linewidth(0.6));
draw(C--footF,dashed+linewidth(0.6));
draw(pointP2--pointP,linewidth(0.7));
draw(footD--footF,linewidth(0.7));
draw(B--pointP,linewidth(0.7));
dot(A);dot(B);dot(C);dot(footD);dot(footE);dot(footF);dot(pointP);dot(pointQ);
label("$A$",A,N);label("$B$",B,SW);label("$C$",C,SE);
label("$D$",footD,S);label("$E$",footE,E);label("$F$",footF,W);
label("$P$",pointP,NE);label("$Q$",pointQ,W);
\end{asy}

solution:
Let $\omega$ be the circumcircle of $ABC$, and let $\sigma$ be the reflection in the line $AB$. Write $P'$ for the intersection point of line $EF$ with $\omega$ that is different from $P$; both are shown in the sketch.


\begin{asy}
usepackage("amsmath");
size(9cm);
defaultpen(fontsize(10pt));
pair perpvec(pair v){return (-v.y,v.x);}
pair inter(pair Z1,pair Z2,pair Z3,pair Z4){
  real a1=Z2.y-Z1.y, b1=Z1.x-Z2.x, c1=a1*Z1.x+b1*Z1.y;
  real a2=Z4.y-Z3.y, b2=Z3.x-Z4.x, c2=a2*Z3.x+b2*Z3.y;
  real det=a1*b2-a2*b1;
  return ((b2*c1-b1*c2)/det,(a1*c2-a2*c1)/det);
}
pair perpfoot(pair X,pair Y,pair Z){
  return Y+(dot(X-Y,Z-Y)/dot(Z-Y,Z-Y))*(Z-Y);
}
pair A=(0,6), B=(-3,0), C=(5,0);
pair footD=perpfoot(A,B,C);
pair footE=perpfoot(B,C,A);
pair footF=perpfoot(C,A,B);
pair O=inter((A+B)/2,(A+B)/2+perpvec(B-A),(A+C)/2,(A+C)/2+perpvec(C-A));
real R=abs(O-A);
pair efv=footE-footF;
