pair A=(0,0), B=(10,0);
pair C2=(b2*ux,b2*uy), C1=(b1*ux,b1*uy);
draw(A--C1,linewidth(0.9));
draw(A--B,linewidth(0.9));
draw(B--C1,linewidth(0.9));
draw(B--C2,blue+linewidth(0.9));
draw(arc(A,1.4,0,30),linewidth(0.6));
dot(A); dot(B); dot(C1); dot(C2);
label("$A$",A,W); label("$B$",B,SE);
label("$C_1$",C1,N); label("$C_2$",C2,NW);
label("$10$",(A+B)/2,S);
label("$6$",(B+C1)/2,E);
