pair f4A1=f4A+f4d, f4B1=f4B+f4d, f4C1=f4C+f4d, f4D1=f4D+f4d;
draw(f4A--f4B--f4C--f4D--cycle,linewidth(0.9));
draw(f4B--f4B1,linewidth(0.9));
draw(f4C--f4C1,linewidth(0.9));
draw(f4D--f4D1,linewidth(0.9));
draw(f4B1--f4C1--f4D1,linewidth(0.9));
draw(f4A1--f4B1,dashed+linewidth(0.7));
draw(f4A1--f4D1,dashed+linewidth(0.7));
draw(f4A--f4A1,dashed+linewidth(0.7));
filldraw(circle(f4A,0.11),black,black);
filldraw(circle(f4C,0.11),black,black);
filldraw(circle(f4B1,0.11),black,black);
filldraw(circle(f4D1,0.11),black,black);
