label("$A$", A, W);
label("$B$", B, SE);
label("$C$", C, NE);
label("$O$", O, SW);
label("$51^\circ$", A+(0.2,0), E);
label("$64.5^\circ$", B+(0.15,-0.05), SW);
label("$64.5^\circ$", C+(0.15,0.05), NW);
label("$102^\circ$", (1.18,0), E);
\end{asy}


\textbf{Case 2: \(A\) lies on the minor arc \(BC\).} Then the arc \(BC\) not containing \(A\) is the major arc, of measure
\[
360^\circ-102^\circ=258^\circ.
\]
Hence
\[
\angle A=\dfrac{1}{2}\cdot258^\circ=129^\circ,
\]
and
\[
\angle B=\angle C=\dfrac{180^\circ-129^\circ}{2}=25.5^\circ.
\]

