defaultpen(fontsize(10pt));
real h=3.0, L=1.6, w=0.6;
void tab(real x0){
  draw((x0-0.4,0)--(x0+4.6,0),linewidth(0.6));
  fill((x0,h-0.15)--(x0+3,h-0.15)--(x0+3,h)--(x0,h)--cycle,gray(0.75));
