  draw((x0+0.2,0)--(x0+0.2,h-0.15),linewidth(1.2)); draw((x0+2.8,0)--(x0+2.8,h-0.15),linewidth(1.2));
}
// Figure 1: upright block on the table, lying block on the floor
tab(0);
filldraw((1.2,h)--(1.2+w,h)--(1.2+w,h+L)--(1.2,h+L)--cycle,palegray);
filldraw((3.3,0)--(3.3+L,0)--(3.3+L,w)--(3.3,w)--cycle,palegray);
draw((1.2+w,h+L)--(4.9,h+L),dashed); draw((3.3+L,w)--(4.9,w),dashed);
draw((4.75,w)--(4.75,h+L),Arrows(5)); label("$r$",(4.75,(w+h+L)/2),E);
label("Figure 1",(2.2,-0.45));
// Figure 2: lying block on the table, upright block on the floor
tab(6.5);
filldraw((7.2,h)--(7.2+L,h)--(7.2+L,h+w)--(7.2,h+w)--cycle,palegray);
filldraw((9.9,0)--(9.9+w,0)--(9.9+w,L)--(9.9,L)--cycle,palegray);
draw((7.2+L,h+w)--(11.3,h+w),dashed); draw((9.9+w,L)--(11.3,L),dashed);
draw((11.15,L)--(11.15,h+w),Arrows(5)); label("$s$",(11.15,(L+h+w)/2),E);
label("Figure 2",(8.7,-0.45));
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
