pair up=(0,H*s*0.9);
draw(P0--P1--P1+up--P0+up--cycle,linewidth(0.8));
draw(P1--P2--P2+up--P1+up,linewidth(0.8));
draw(P0+up--P3+up--P2+up,linewidth(0.8));
draw(P0--P3--P2,dashed+gray);
draw(P3--P3+up,dashed+gray);
draw(P0--P2+up,red+linewidth(0.9));
