size(6.5cm);
defaultpen(fontsize(10pt));
real s=13.5;
pair B=(0,0), C=(23,0);
real hgt=sqrt(s^2-11.5^2);
pair A=(11.5,hgt), P=(9,0), Q=(14,0);
draw(A--B--C--cycle,linewidth(0.8));
draw(A--P,blue); draw(A--Q,blue);
dot(A);dot(B);dot(C);dot(P);dot(Q);
label("$A$",A,N); label("$B$",B,SW); label("$C$",C,SE); label("$P$",P,S); label("$Q$",Q,S);
label("$9$",(B+P)/2,S); label("$5$",(P+Q)/2,S); label("$9$",(Q+C)/2,S);
label("$s$",(A+B)/2,NW); label("$s$",(A+C)/2,NE); label("$t$",(A+P)/2,W); label("$t$",(A+Q)/2,E);
draw(arc(A,2.2,degrees(B-A),degrees(P-A))); draw(arc(A,2.5,degrees(P-A),degrees(Q-A))); draw(arc(A,2.2,degrees(Q-A),degrees(C-A)));
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

\textbf{Angle bisector theorem.} Since $AP$ and $AQ$ trisect $\angle BAC$, we have $\angle PAQ=\angle QAC$, so in triangle $APC$ the segment $AQ$ bisects $\angle PAC$. Hence
\[\dfrac{PQ}{QC}=\dfrac{AP}{AC}\quad\Longrightarrow\quad\dfrac{5}{9}=\dfrac {t}{s}\quad\Longrightarrow\quad t=\dfrac{5s}{9}.\]

\textbf{Stewart's theorem.} In triangle $ABC$ with cevian $AP$, where $BP=9$ and $PC=14$,
\[AB^2\cdot PC+AC^2\cdot BP=BC\left(AP^2+BP\cdot PC\right)\ \Longrightarrow\ 14s^2+9s^2=23\left(t^2+126\right),\]
so $s^2=t^2+126$. Substituting $t=\dfrac{5s}{9}$,
\[s^2-\dfrac{25s^2}{81}=126\ \Longrightarrow\ \dfrac{56s^2}{81}=126\ \Longrightarrow\ s^2=\dfrac{729}{4},\quad s=\dfrac{27}{2}.\]
(Check: then $t=\dfrac{15}{2}$, and the height is $\sqrt{s^2-11.5^2}=\sqrt{50}$, consistent with $t^2=2.5^2+50=56.25$.)

The perimeter is $2s+23=27+23=\boxed{50}$.

question:
Find all quadruples $(a,b,c,d)$ such that
\[ac=6,\qquad ad=4,\qquad bc=9,\qquad bd=6,\]
\begin{enumerate}
\item[(a)] when $a,b,c,d$ are real numbers;
\item[(b)] when $a,b,c,d$ are integers.
\end{enumerate}

solution:
Let the room be $[0,10]^3$ with $A=(0,0,0)$ on the floor and $B=(10,10,10)$ on the ceiling.

\textbf{A path of length $10\sqrt5$.} Unfold the front wall and the right wall, which share a vertical edge, into one flat $20\times10$ rectangle. In this net $A$ and $B$ are opposite corners, so the straight segment between them has length $\sqrt{20^2+10^2}=10\sqrt5$. Folding back, this segment is a path on the two walls that crosses the shared edge at its midpoint $M$.

\begin{asy}
usepackage("amsmath");
size(9cm);
defaultpen(fontsize(10pt));
// left: oblique cube with the shortest path; right: unfolded two faces
pair o=(0.45,0.32);
real a=10;
pair p000=(0,0), p100=(a,0), p010=a*o, p110=(a,0)+a*o;
pair up=(0,a);
draw(p000--p100--p100+up--p000+up--cycle,linewidth(0.8));
draw(p100--p110--p110+up--p100+up,linewidth(0.8));
draw(p000+up--p010+up--p110+up,linewidth(0.8));
draw(p000--p010--p110,dashed+gray); draw(p010--p010+up,dashed+gray);
pair Mid=p100+up/2;
draw(p000--Mid--p110+up,red+linewidth(1));
dot(p000);dot(p110+up);dot(Mid,red);
label("$A$",p000,SW); label("$B$",p110+up,NE); label("$M$",Mid,E,red);
// net
pair s=(24,0);
draw(s--s+(20,0)--s+(20,10)--s--cycle,white);
draw(s--s+(10,0)--s+(10,10)--s+(0,10)--cycle,linewidth(0.8));
draw(s+(10,0)--s+(20,0)--s+(20,10)--s+(10,10),linewidth(0.8));
draw(s--s+(20,10),red+linewidth(1));
dot(s);dot(s+(20,10));dot(s+(10,5),red);
label("$A$",s,SW); label("$B$",s+(20,10),NE); label("$M$",s+(10,5),SE,red);
label("$10$",s+(5,0),S); label("$10$",s+(15,0),S); label("$10$",s+(20,5),E);
