defaultpen(fontsize(10pt));
pair A=(0,0), B=(6,0), C=(3,5.196);
real d=0.7;
pair I=(A+B+C)/3; real rin=5.196/3;
real k=(rin-d)/rin;
pair A1=I+k*(A-I), B1=I+k*(B-I), C1=I+k*(C-I);
filldraw(A--B--C--cycle,palered,black+1);
filldraw(A1--B1--C1--cycle,white,black);
dot(I); label("$I$",I,W);
draw(I--I+k*((A+B)/2-I),dashed); draw(I+k*((A+B)/2-I)--(A+B)/2,linewidth(1.2)+blue);
label("$6$",((A+B)/2+I+k*((A+B)/2-I))/2,E,blue);
label("$A$",A,SW);label("$B$",B,SE);label("$C$",C,N);
label("$A'$",A1,NE);label("$B'$",B1,NW);label("$C'$",C1,E);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

Place $B=(0,0)$, $C=(2,0)$, $A=(1,\sqrt3)$. Then $AB$ is the line $y=\sqrt3\,x$ and $AC$ is the line $y=\sqrt3\,(2-x)$.

Let $Q=(q,0)$ and write $\overrightarrow{QP}=(-a,b)$. In the square $PQRS$ the vector $\overrightarrow{QR}$ is $\overrightarrow{QP}$ turned through $90^\circ$ (towards $C$), so $\overrightarrow{QR}=(b,a)$, and $S=P+\overrightarrow{QR}$:
\[
P=(q-a,\ b),\qquad R=(q+b,\ a),\qquad S=(q-a+b,\ a+b).
\]
The conditions $P\in AB$ and $R\in AC$ give
\[
b=\sqrt3\,(q-a),\qquad a=\sqrt3\,(2-q-b).
\]
Adding them, the $q$ terms cancel:
\[
a+b=\sqrt3\,(2-a-b)\quad\Longrightarrow\quad (a+b)(1+\sqrt3)=2\sqrt3\quad\Longrightarrow\quad a+b=\dfrac{2\sqrt3}{1+\sqrt3}=3-\sqrt3 .
\]
So the $y$-coordinate of $S$ is always $3-\sqrt3$, whatever the position of the square: $S$ stays on the line $y=3-\sqrt3$, which is parallel to $BC$. Since $S$ moves continuously from a point of $AC$ to a point of $AB$, it traces the segment of this line inside the triangle.

\begin{asy}
usepackage("amsmath");
size(6.5cm);
defaultpen(fontsize(10pt));
real s3=sqrt(3);
pair B=(0,0), C=(2,0), A=(1,s3);
draw(A--B--C--cycle,linewidth(0.9));
real h=3-s3;
draw((-0.3,h)--(2.3,h),dashed+blue);
label("$y=3-\sqrt3$",(2.3,h),E,blue);
real q=0.98;
real aa=(3*q-s3*(2-q))/2;
real bb=s3*(q-aa);
pair Q=(q,0), P=(q-aa,bb), R=(q+bb,aa), Sx=P+R-Q;
filldraw(P--Q--R--Sx--cycle,paleblue,black);
dot(P);dot(Q);dot(R);dot(Sx,red);
pair S0=(h/s3,h), S1=(2-h/s3,h);
draw(S0--S1,blue+1.3); dot(S0,blue); dot(S1,blue);
label("$P$",P,W);label("$Q$",Q,S);label("$R$",R,E);label("$S$",Sx,N,red);
label("$A$",A,N);label("$B$",B,SW);label("$C$",C,SE);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

Thus the path of $S$ is a segment parallel to $BC$ at distance $\boxed{3-\sqrt3}$ from it. $\blacksquare$

