draw(C--D,blue); draw(D--Ep,red);
draw((0,0.35)--(0.35,0.35)--(0.35,0));
pair u=unit(C-D), v=unit(Ep-D); draw(D+0.35*u--D+0.35*(u+v)--D+0.35*v);
label("$A$",A,NW); label("$B$",B,SE); label("$C$",C,SW); label("$D$",D,NE); label("$E$",Ep,S);
label("$4$",(A+C)/2,W); label("$4$",(C+D)/2,NW,blue); label("$3$",(D+Ep)/2,E,red); label("$3$",(Ep+B)/2,S); label("$5$",(C+Ep)/2,S);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

Hence $AD:DB=8:12=\boxed{\textbf{(A)}\ 2:3}$.

Write $n=\overline{abcba}$ and $7n=\overline{deffed}$. Since $7n\le7\cdot99999<700000$, we have $d\le6$; and $d$ is the units digit of $7n$, i.e.\ of $7a$.
\begin{itemize}
\item $a=9$: $7a=63$ gives $d=3$, but $7n\ge630000$ has first digit $6$. Impossible.
\item $a=8$: $d=6$ (from $56$). Then $7n\ge600000$, so $n\ge85715$; also $7n\le7\cdot89998<630000$, so $e\in\{0,1,2\}$.
\end{itemize}
For $a=8$, compare the last two digits: $7\cdot\overline{b8}=70b+56$ must end in $\overline{e6}$, so $7b+5\equiv e\pmod{10}$. This gives $b=5$ for $e=0$, $b=8$ for $e=1$ and $b=1$ for $e=2$. Since $n\ge85715$, $b\ge5$.

\begin{itemize}
\item $b=8$, $e=1$: $n=\overline{88c88}$ and $7n=616616+700c$, which must have the form $\overline{61ff16}$. For $c=0$ we get $616616$, a palindrome; for $c=1,\dots,4$ we get $617316,618016,618716,619416$ (middle digits unequal), and for $c\ge5$ the number is at least $620116$, so its second digit is no longer $1$.
\item $b=5$ gives $n<86000<88088$.
\end{itemize}
So the greatest such $n$ is $\boxed{88088}$, with $7\cdot88088=616616$.

A rectangle with perimeter $144$ has length and width $\ell$ and $72-\ell$, where $1\le\ell\le71$ is an integer. Its area is
\[
\ell(72-\ell)=1296-(36-\ell)^2 .
\]
The area is largest, $1296$, when $\ell=36$ (the $36\times36$ square), and smallest when $|36-\ell|$ is as large as possible, $\ell=1$ or $71$, giving $1\cdot71=71$.

\begin{asy}
