real th=55; pair u=dir(th);
real t1=-dot(P,u)+sqrt(dot(P,u)^2-(dot(P,P)-289)), t2=-dot(P,u)-sqrt(dot(P,u)^2-(dot(P,P)-289));
draw(P+t1*u--P+t2*u,gray(0.4));
