draw((-3.6,0)--(5.6,0),gray(0.7));draw((0,-3.4)--(0,3.4),gray(0.7));
draw(circle((1,1),2),dashed+gray(0.5));draw(circle((1,-1),2),dashed+gray(0.5));
draw(circle((0,1+sqrt(3)),2),linewidth(0.9));
for(int i=0;i<6;++i) dot(p[i]);
label("$(-1,1)$",p[0],SW,fontsize(8pt));label("$(1,1)$",p[1],S,fontsize(8pt));label("$(3,1)$",p[2],SE,fontsize(8pt));
label("$(-1,-1)$",p[3],SW,fontsize(8pt));label("$(1,-1)$",p[4],S,fontsize(8pt));label("$(3,-1)$",p[5],SE,fontsize(8pt));
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

The answer is $\boxed{18}$. (One of them, centred at $(0,1+\sqrt3)$ through $(-1,1)$ and $(1,1)$, is drawn solid.)

