pair J=extension(F,H,G,I);
pair K=(J.x,0);
draw(G--H--I--cycle,linewidth(1));draw(G--F--H,linewidth(1));
draw(J--K,dashed);
real s=0.35;
draw((s,0)--(s,s)--(0,s));draw((6-s,0)--(6-s,s)--(6,s));draw(K+(s,0)--K+(s,s)--K+(0,s));
