draw(P(0,0,0)--P(a,0,0)--P(a,0,c)--P(0,0,c)--cycle,linewidth(0.9));
draw(P(a,0,0)--P(a,b,0)--P(a,b,c)--P(a,0,c),linewidth(0.9));
draw(P(0,0,c)--P(0,b,c)--P(a,b,c),linewidth(0.9));
for(int i=1;i<6;++i){draw(P(i,0,0)--P(i,0,c),gray(0.5));draw(P(i,0,c)--P(i,b,c),gray(0.5));}
for(int k=1;k<3;++k){draw(P(0,0,k)--P(a,0,k),gray(0.5));draw(P(a,0,k)--P(a,b,k),gray(0.5));}
for(int j=1;j<4;++j){draw(P(a,j,0)--P(a,j,c),gray(0.5));draw(P(0,j,c)--P(a,j,c),gray(0.5));}
label("$168$",P(a/2,0,0),S);label("$112$",P(a,b/2,0),SE);label("$84$",P(0,0,c/2),W);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

