defaultpen(fontsize(10pt));
pair A=(0,4),B=(6,4),C=(6,0),D=(0,0),E=(3,0),Dp=(96/25,72/25);
draw(A--B--C--D--cycle,linewidth(0.9));
draw(A--E,linewidth(0.9));
draw(A--Dp--E,blue+linewidth(0.9));
draw(D--Dp,dashed);draw(Dp--C,red+linewidth(1));
label("$A$",A,NW);label("$B$",B,NE);label("$C$",C,SE);label("$D$",D,SW);label("$E$",E,S);label("$D'$",Dp,N);
label("$4$",(A+D)/2,W);label("$3$",(D+E)/2,S);label("$3$",(E+C)/2,S);label("$5$",(A+E)/2,SW);
dot(Dp);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
