draw((0,0)--(20,10)--(2,19)--(0,18)--(20,8)--(4,0)--(0,2)--(20,12)--(6,19)--(0,16)--(20,6)--(8,0)--(0,4)--(20,14)--(10,19)--(0,14)--(20,4)--(12,0)--(0,6)--(20,16)--(14,19)--(0,12)--(20,2)--(16,0)--(0,8)--(20,18)--(18,19)--(0,10)--(20,0),blue+linewidth(0.6));
