label("$(0,0)$",(0,0),SW);label("$(20,0)$",(20,0),SE);label("$(20,19)$",(20,19),NE);label("$(0,19)$",(0,19),NW);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

\textbf{Mass points.} Put masses on the vertices so that $E$ and $D$ are balance points. For $E$ on $AB$ with $AE:EB=3:2$ we need $3m_A=2m_B$; for $D$ on $AC$ with $AD:DC=1:4$ we need $m_A=4m_C$. Take $m_A=2$, $m_B=3$, $m_C=\dfrac{1}{2}$.

