defaultpen(fontsize(10pt));
real s=18;pair A=(0,0),B=(s,0),C=s*dir(60);
pair p(real i,real j){return A+i*(B-A)/3+j*(C-A)/3;}
fill(p(0,0)--p(1,0)--p(0,1)--cycle,palegray);
fill(p(2,0)--p(3,0)--p(2,1)--cycle,palegray);
fill(p(0,2)--p(1,2)--p(0,3)--cycle,palegray);
draw(A--B--C--cycle,linewidth(1));
draw(p(1,0)--p(2,0)--p(2,1)--p(1,2)--p(0,2)--p(0,1)--cycle,blue+linewidth(1.2));
