for(int k=2;k<5;++k) P.push(P[k-1]+dir(-72*(k-1)));
draw(H[0]--H[1]--H[2]--H[3]--H[4]--H[5]--cycle,linewidth(1));
draw(P[0]--P[1]--P[2]--P[3]--P[4]--cycle,linewidth(1));
draw(H[0]--H[1],red+linewidth(2));
