defaultpen(fontsize(10pt));
for(int i=0;i<=5;++i){draw((i,0)--(i,5),gray(0.8));draw((0,i)--(5,i),gray(0.8));}
pair P1=(0,0),P2=(4,1),P3=(5,3),P4=(1,5),P5=(0,2);
fill(P1--P2--P3--P4--P5--cycle,rgb(0.85,0.92,1));
draw(P1--P3,dashed);draw(P1--P4,dashed);
draw(P1--P2--P3--P4--P5--cycle,linewidth(1));
dot(P1);dot(P2);dot(P3);dot(P4);dot(P5);
label("$P_1$",P1,SW);label("$P_2$",P2,SE);label("$P_3$",P3,E);label("$P_4$",P4,N);label("$P_5$",P5,W);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

For example, the pentagon $P_1P_2P_3P_4P_5$ with vertices $(0,0),(4,1),(5,3),(1,5),(0,2)$ splits into triangles with doubled areas $7$, $22$ and $2$, so $2A=31$ and $A=\dfrac{31}{2}$. Equivalently, the shoelace formula $A=\dfrac{1}{2}\left|\sum_{i=1}^{n}\left(x_iy_{i+1}-x_{i+1}y_i\right)\right|$ (indices modulo $n$) is half the absolute value of a sum of integers. (Pick's theorem, $A=I+\dfrac {B}{2}-1$, gives the same conclusion.)

Group the numbers $50,\dots,100$ by their partner $130-x$:
\begin{itemize}
\item the $15$ pairs $\{50,80\},\{51,79\},\dots,\{64,66\}$;
\item $65$, whose partner is itself (but the two elements must be distinct, so $65$ is harmless);
\item $81,82,\dots,100$, whose partners $49,\dots,30$ are outside the set.
\end{itemize}
This splits the $51$ numbers into $15+1+20=36$ groups, and $S$ contains at most one number from each pair, so $|S|\le36$. The set $\{50,\dots,65\}\cup\{81,\dots,100\}$ has $16+20=36$ elements and works: two distinct numbers from the first part sum to at most $64+65=129$, and any sum involving the second part is at least $50+81=131$. The maximum is $\boxed{36}$.

question:
