draw((t,0)--(0,t),blue);draw((2-t,0)--(2,t),blue);draw((2,2-t)--(2-t,2),blue);draw((t,2)--(0,2-t),blue);
draw(A--B--C--D--cycle,linewidth(1));
draw(P--A);draw(P--B);draw(P--C);draw(P--D);
