pen g=gray(0.7)+linewidth(0.4);
for(int i=1;i<6;++i){draw(p(i,0,0)--p(i,0,3),g);draw(p(i,0,3)--p(i,4,3),g);}
for(int k=1;k<3;++k){draw(p(0,0,k)--p(6,0,k),g);draw(p(6,0,k)--p(6,4,k),g);}
for(int j=1;j<4;++j){draw(p(0,j,3)--p(6,j,3),g);draw(p(6,j,0)--p(6,j,3),g);}
