usepackage("amsmath");
size(6.5cm);
defaultpen(fontsize(10pt));
import graph;
real f1(real x){return x^2;}
real f2(real x){return x^2/2;}
draw((-3.4,0)--(3.4,0),gray(0.7),Arrow(5));
draw((0,-0.5)--(0,5),gray(0.7),Arrow(5));
draw(graph(f1,-2.15,2.15),blue+linewidth(0.9));
