real r=12/(4+pi), h=r;
pair A=(-r,0),B=(r,0),C=(r,h),D=(-r,h);
draw(A--B--C--arc((0,h),r,0,180)--D--A,linewidth(1));
draw(D--C,dashed);
draw((0,h)--(0,h)+r*dir(55),gray(0.4));
