real R=85/8; pair D=2*O-A;
draw(circle(O,R),gray);
draw(A--B--C--cycle,linewidth(1));
draw(A--H,dashed);draw(A--D,blue+dashed);draw(D--C,blue);
real s=0.8;
draw(H+(s,0)--H+(s,s)--H+(0,s));
pair u=unit(A-C),v=unit(D-C);
draw(C+s*u--C+s*(u+v)--C+s*v);
