label("$x$",(4,0),S,gray(0.4));label("$y$",(0,4.3),E,gray(0.4));
pair P=(0,8/3),Q=(3,-4/3);
draw((-0.6,8/3+0.8)--(3.4,-4/3-0.5333),linewidth(1)+blue);
draw(P--(3,8/3),dashed);draw((3,8/3)--Q,dashed);
dot(P);dot(Q);
