pair Bf=B+0.75*(B-A),Cf=C+0.55*(C-A);
draw(A--B--C--cycle,linewidth(1));
draw(B--Bf);draw(C--Cf);
draw(B--X,dashed+blue);draw(C--X,dashed+blue);
draw(arc(X,0.6,degrees(C-X),degrees(B-X)),red);
label("$?$",X+0.95*dir((degrees(C-X)+degrees(B-X))/2),red);
draw(arc(B,0.5,0,degrees(X-B)),blue);draw(arc(B,0.5,degrees(X-B),degrees(C-B)),blue);
draw(arc(C,0.5,degrees(B-C)-360,degrees(X-C)),deepgreen);draw(arc(C,0.6,degrees(B-C)-360,degrees(X-C)),deepgreen);draw(arc(C,0.5,degrees(X-C),degrees(Cf-C)),deepgreen);draw(arc(C,0.6,degrees(X-C),degrees(Cf-C)),deepgreen);
dot(A);dot(B);dot(C);dot(X,blue);
label("$A$",A,SW);label("$B$",B,S);label("$C$",C,W);label("$X$",X,E,blue);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
