draw(A0--(Q+0.15*(Q-A0)),blue+linewidth(0.8));
dot(P);dot(Q);dot(M,red);dot(A0);dot((1,0));
label("$P$",P,NW);label("$Q$",Q,NW);label("$M$",M,SE);
