size(6cm);
defaultpen(fontsize(10pt));
pair A=(0,0),B=(14,0);
real c=12;
real x=(14^2+4^2-c^2)/(2*14);
pair C=(x,sqrt(16-x^2));
draw(A--B--C--cycle,linewidth(1));
dot(A);dot(B);dot(C);
label("$14$",(A+B)/2,S);label("$4$",(A+C)/2,NW);label("$c$",(B+C)/2,2*dir(75));
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

The semiperimeter is $s=\dfrac{4+14+c}{2}=9+\dfrac {c}{2}$, which takes every value with $9+5<s<9+9$. So
\[
\boxed{14<s<18}.
\]

Let $O$ be the centre of the large circle, $Q$ the centre of the small circle, and $T$ the point where the circles touch. Since the circles are internally tangent, $O$, $Q$, $T$ are collinear and $OQ=1000-320=680$. The small circle touches the diameter at $P$, so $QP\perp OP$ and $QP=320$.

\begin{asy}
usepackage("amsmath");
size(6cm);
defaultpen(fontsize(10pt));
real R=10,r=3.2;
pair O=(0,0),Q=(6,r),P=(6,0),T=R*unit(Q),X=(R,0);
draw(circle(O,R),linewidth(0.9));
draw((-R,0)--(R,0),linewidth(0.8));
draw(circle(Q,r),linewidth(0.9));
draw(O--T,dashed);draw(Q--P,dashed);
draw(P--X,blue+linewidth(1.2));
dot(O);dot(Q);dot(P);dot(T);dot(X);
label("$O$",O,S);label("$Q$",Q,NW);label("$P$",P,S);label("$T$",T,NE);label("$X$",X,E);
label("$320$",(Q+P)/2,E);label("$600$",(O+P)/2,S);label("$400$",(P+X)/2,S,blue);
label("\mbox{}",(min(currentpicture,user=true)+max(currentpicture,user=true))/2,black); // keeps the text after the figure black when LaTeX typesets the labels inline
\end{asy}

By the Pythagorean theorem, $OP=\sqrt{680^2-320^2}=\sqrt{(680-320)(680+320)}=\sqrt{360000}=600$. The point of the large circle nearest to $P$ is the end $X$ of the diameter on the ray $OP$ (for any point $Y$ on the circle, $PY\ge OY-OP=1000-600$), so the distance from $P$ to the large circle is
\[
PX=1000-600=\boxed{400}.
\]

Enclose the triangle in the rectangle $1\le x\le5$, $1\le y\le4$, of area $4\cdot3=12$. The part of the rectangle outside the triangle consists of three right triangles:
\begin{itemize}
\item below $AB$: legs $4$ and $2$, area $4$;
\item to the right of $BC$: legs $1$ and $3$, area $\dfrac{3}{2}$;
\item above $CA$: legs $3$ and $1$, area $\dfrac{3}{2}$.
\end{itemize}
So $[ABC]=12-4-\dfrac{3}{2}-\dfrac{3}{2}=5$. (The shoelace formula gives the same: $\dfrac{1}{2}\left|1(1-4)+5(4-3)+4(3-1)\right|=5$.) The grid has area $6\cdot5=30$, so the fraction is $\dfrac{5}{30}=\boxed{\textbf{(A) }\dfrac{1}{6}}$.

\begin{asy}
