pair B=(0,0),A=(4,0),C=(0,4),D=(4,8),Ee=(8,4);
draw(A--B--C--cycle,linewidth(0.9));draw(A--C--D--Ee--cycle,linewidth(0.9));
draw((0.5,0)--(0.5,0.5)--(0,0.5));
draw(B--Ee,red+linewidth(0.9));draw(A--(8,0)--Ee,dashed);
